/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A59 frozen manifest; 20-lemma checkpoints are validated before publication. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});
D('kymograph',{etymology:E('Kymograph combines Greek kyma “wave” and graphein “to write”; it names an instrument that records a changing movement or pressure as a trace over time.','kymograph'),contexts:[C('kymograph.s1','生理实验','The kymograph recorded the muscle’s contractions as a rising and falling line while the stimulus was repeated.','刺激反复施加时，记波仪将肌肉收缩记录为起伏的曲线。','The kymograph recorded the muscle’s contractions / as a rising and falling line / while the stimulus was repeated.','kymograph 是把生理或机械变化随时间描成图线的仪器。','曲线显示刺激过程中收缩强弱随时间变化。')],mistakes:[M('The researcher used a kymograph to record a single still photograph of the room, with no changing motion or pressure to trace.','The researcher used a kymograph to trace the changing pressure of the pulse over time.','记波仪记录随时间变化的过程，不是单张静态照片。')],quiz:[Q('kymograph',1,1,'A kymograph records?','a changing process as a trace over time','a still image with no changing measurement','a list of laboratory staff','a changing process as a trace over time','kymograph 将变化过程记录成随时间变化的图线。'),Q('kymograph',2,1,'Which measurement suits a kymograph?','the changing pressure of a pulse','the color of an unchanged wall','the spelling of a word','the changing pressure of a pulse','脉搏压力会随时间变化，适合记录成曲线。'),Q('kymograph',3,1,'The Greek element graph in kymograph is associated with?','writing or recording','an island','a prison guard','writing or recording','-graph 与记录或书写有关。','word-formation'),Q('kymograph',4,1,'A kymograph trace can help researchers see?','when a muscle contracts and relaxes','which employee owns a ladder','whether a drink contains lace','when a muscle contracts and relaxes','曲线可显示肌肉收缩和放松的时间。')]});
D('lab',{etymology:E('Lab is a shortened form of laboratory; it can mean a room for scientific experiments or a place used for research and practical instruction.','lab'),contexts:[C('lab.s1','化学课','Students wore goggles in the lab while they measured the reaction between the two solutions.','学生在实验室测量两种溶液的反应时都戴着护目镜。','Students wore goggles in the lab / while they measured / the reaction between the two solutions.','lab.s1 指进行科学实验的房间。','学生在受控场所用仪器观察化学反应。')],mistakes:[M('The school called the cafeteria a chemistry lab even though it had no instruments, experiments, or research activity.','The school called the room with test tubes and experiment benches a chemistry lab.','仅供应午餐的食堂不具备实验室功能。')],quiz:[Q('lab',1,1,'In a science class, a lab is a place to?','carry out experiments','serve meals to customers','store travel itineraries','carry out experiments','lab.s1 是进行实验的场所。'),Q('lab',2,2,'A university research lab may be used for?','research or practical study','serving as a country’s capital','holding prisoners','research or practical study','lab.s2 也可指研究室或实践教学场所。'),Q('lab',3,1,'“The samples were tested in the lab” means they were tested?','in a laboratory','on a sports field','at a restaurant','in a laboratory','lab 是 laboratory 的缩写。','word-formation'),Q('lab',4,1,'Which item is most at home in a lab?','a labeled test tube','a dinner menu','a beach umbrella','a labeled test tube','试管常用于实验室。')]});
D('labellum',{etymology:E('Labellum is a botanical term from Latin labellum, a diminutive of labium “lip”; in orchids it names the modified petal that forms a lip.','labellum'),contexts:[C('labellum.s1','植物形态学','The botanist photographed the orchid’s labellum, whose broad lip guided an insect toward the flower’s nectar.','植物学家拍下兰花的唇瓣；宽大的唇形花瓣引导昆虫靠近花蜜。','The botanist photographed the orchid’s labellum / whose broad lip guided an insect / toward the flower’s nectar.','labellum 是兰花中形态特化、像唇部的花瓣。','唇瓣的形状帮助传粉昆虫找到花蜜。')],mistakes:[M('The botanist labeled an orchid’s root a labellum because it grew underground and absorbed water.','The botanist labeled the orchid’s modified lip-shaped petal its labellum.','labellum 是兰花的特化花瓣，不是吸水的根。')],quiz:[Q('labellum',1,1,'An orchid’s labellum is a modified?','petal shaped like a lip','root that absorbs water','seed that grows underground','petal shaped like a lip','labellum 指兰花唇瓣，即唇形特化花瓣。'),Q('labellum',2,1,'What may the labellum help an orchid do?','guide pollinators toward nectar','anchor its roots in soil','store water in its stem','guide pollinators toward nectar','唇瓣可引导传粉者接近花蜜。'),Q('labellum',3,1,'Labellum is a term from?','botany','ship loading','sports law','botany','labellum 是植物学术语。'),Q('labellum',4,1,'Which part would a botanist identify as the labellum?','the flower’s distinctive lip-like petal','the flower’s underground root','the insect visiting the flower','the flower’s distinctive lip-like petal','兰花中唇形显著花瓣就是唇瓣。')]});
D('laborer',{etymology:E('Laborer is formed from labor with the agent suffix -er; it names a worker whose job involves physical effort, often skilled or semi-skilled manual tasks.','laborer'),contexts:[C('laborer.s1','建筑工地','The laborer carried blocks to the crew and cleared debris from the marked walkway before deliveries arrived.','工人把砌块搬给施工队，并在材料送达前清理了标记的人行通道。','The laborer carried blocks to the crew / and cleared debris / from the marked walkway / before deliveries arrived.','laborer 指主要从事体力劳动的工人。','搬运材料和清理施工通道是体力工作。')],mistakes:[M('The article called the finance director a laborer solely because she approved a payroll, although she did no physical or manual work.','The article called the worker who carried materials and cleared the site a laborer.','仅处理工资账目不能据此称为体力劳动者。')],quiz:[Q('laborer',1,1,'A laborer typically does?','physical or manual work','only financial auditing','botanical classification','physical or manual work','laborer 指从事体力劳动的工人。'),Q('laborer',2,1,'Which task is most typical of a laborer?','moving building materials at a worksite','editing a magazine issue at home','analyzing an orchid’s petals only','moving building materials at a worksite','搬运建筑材料属于体力劳动。'),Q('laborer',3,1,'Laborer is formed from labor plus?','-er','-ous','-ity','-er','-er 在此构成表示劳动者的名词。','word-formation'),Q('laborer',4,1,'A laborer clearing debris is doing?','manual work','an act of medical isolation','a literary allusion','manual work','清理碎屑需要体力劳动。')]});
D('laborious',{etymology:E('Laborious comes from Latin laboriosus, from labor “work”; it describes work that takes sustained effort or, less commonly, a person who works hard.','laborious'),contexts:[C('laborious.s1','档案整理','Digitizing the damaged ledger was laborious because each faint handwritten entry had to be checked against a second copy.','将受损账簿数字化十分费力，因为每条模糊的手写记录都必须与另一份副本核对。','Digitizing the damaged ledger was laborious / because each faint handwritten entry / had to be checked / against a second copy.','laborious.s1 描述耗时且需要大量努力的工作。','每条记录都要仔细辨认和复核，过程繁重。')],mistakes:[M('The scan was called laborious even though the entire thousand-page ledger was converted accurately in a few seconds without review.','The scan was laborious because each page required careful correction and repeated checking.','无需核查、瞬间完成的工作并不费力繁重。')],quiz:[Q('laborious',1,1,'A laborious task requires?','a great deal of time and effort','no attention or work','a single brief glance','a great deal of time and effort','laborious.s1 指费时费力的。'),Q('laborious',2,2,'A laborious writer, in the less common sense, is?','hard-working','unable to work','a person who guards a jail','hard-working','laborious.s2 也可形容勤劳的人，较少见。'),Q('laborious',3,1,'Which task is laborious?','checking thousands of faint entries one by one','opening a clear one-page file','reading a short printed label','checking thousands of faint entries one by one','逐条核对大量模糊记录十分费力。'),Q('laborious',4,1,'Laborious is closest to?','arduous','effortless','laborsaving','arduous','arduous 表示艰巨费力的。','confusable')]});
D('laboriously',{etymology:E('Laboriously is the adverb formed from laborious with -ly; it describes doing something with slow, sustained effort.','laboriously'),contexts:[C('laboriously.s1','手工修复','The conservator laboriously lifted each brittle layer with a fine tool so the original ink would remain intact.','修复人员用精细工具费力地一层层揭起脆弱纸层，以保留原有墨迹。','The conservator laboriously lifted each brittle layer / with a fine tool / so the original ink / would remain intact.','laboriously 表示缓慢、持续并需要很大努力地做某事。','修复者逐层细致操作以免损坏墨迹。')],mistakes:[M('He completed the intricate repair laboriously by making one effortless movement in less than a second.','He completed the intricate repair laboriously through many careful, slow adjustments.','毫不费力的一次动作与 laboriously 的费力过程不符。')],quiz:[Q('laboriously',1,1,'To work laboriously is to work?','with slow and sustained effort','without any effort','only in a laboratory','with slow and sustained effort','laboriously 指费力地、艰难地。'),Q('laboriously',2,1,'Which action is done laboriously?','carefully restoring a fragile book page over several hours','turning on a lamp with one quick touch','reading a large clear sign at a glance','carefully restoring a fragile book page over several hours','耗时数小时修复脆弱书页需要持续努力。'),Q('laboriously',3,1,'Laboriously is the adverb from?','laborious','laborer','labour-saving','laborious','laboriously 由 laborious 加 -ly 构成。','word-formation'),Q('laboriously',4,1,'A laboriously assembled model was probably?','put together slowly with considerable care','finished instantly without work','abandoned before assembly','put together slowly with considerable care','仔细缓慢地组装体现 laboriously。')]});
D('laborsaving',{etymology:E('Laborsaving combines labor and saving; it describes a tool or method that reduces the amount of human work required.','laborsaving'),contexts:[C('laborsaving.s1','家务工具','The laborsaving dishwasher freed the restaurant staff from washing hundreds of plates by hand after each shift.','这台省力洗碗机让餐厅员工不必每班结束后手洗数百只盘子。','The laborsaving dishwasher freed the restaurant staff / from washing hundreds of plates by hand / after each shift.','laborsaving 作形容词，指能减少人工劳动的。','机器替代大量手洗工作，降低人力负担。')],mistakes:[M('The factory called the new machine laborsaving even though it added hours of manual sorting to every worker’s shift.','The factory called the new machine laborsaving because it handled the sorting that workers had done by hand.','增加人工工时的设备没有节省劳动。')],quiz:[Q('laborsaving',1,1,'A laborsaving device?','reduces the human effort needed','creates more manual work','records muscle movement','reduces the human effort needed','laborsaving 指节省人力的。'),Q('laborsaving',2,1,'Which invention is laborsaving?','a machine that washes dishes automatically','a tool that requires each dish to be scrubbed twice','a list of cleaning duties','a machine that washes dishes automatically','自动洗碗减少了手工劳动。'),Q('laborsaving',3,1,'The word laborsaving combines labor with?','saving','laden','lacuna','saving','laborsaving 是 labor 与 saving 的复合词。','word-formation'),Q('laborsaving',4,1,'A laborsaving process is useful when it?','cuts the time or effort workers must spend','adds repeated handwork','makes the same task harder','cuts the time or effort workers must spend','节省工时或体力是该词的关键。')]});
D('labyrinth',{etymology:E('Labyrinth comes through Latin from Greek labyrinthos; it can mean a maze of passages or, figuratively, a highly complicated system.','labyrinth'),contexts:[C('labyrinth.s2','行政流程','New applicants found the licensing rules a labyrinth of forms, exceptions, deadlines, and offices.','新申请人发现，许可规定像迷宫一样，充满表格、例外条款、期限和办事部门。','New applicants found the licensing rules / a labyrinth of forms / exceptions, deadlines, and offices.','labyrinth.s2 比喻结构复杂、难以弄清的系统或事物。','多种表格、例外和部门让规定难以理解。')],mistakes:[M('The short application was a labyrinth because it had one clear form, one deadline, and no exceptions or referrals.','The application system was a labyrinth because it sent people through many offices and conflicting forms.','流程简单清晰，不符合迷宫般复杂的比喻义。')],quiz:[Q('labyrinth',1,1,'A literal labyrinth is a?','maze of paths or passages','single straight corridor','labor-saving machine','maze of paths or passages','labyrinth.s1 指迷宫。'),Q('labyrinth',2,2,'A labyrinth of regulations is?','a confusingly complicated system','one short and clear rule','a small island','a confusingly complicated system','labyrinth.s2 比喻复杂难懂的事物。'),Q('labyrinth',3,2,'Which situation is a labyrinth?','an application that passes through many confusing offices','a form completed in one step','a path with a single sign and no turns','an application that passes through many confusing offices','复杂的多部门审批像迷宫一样难理清。'),Q('labyrinth',4,1,'A person lost in a labyrinth may struggle to?','find a route through its passages','operate a dishwasher','identify an isotope','find a route through its passages','迷宫里路径错综，难以找到出路。')]});
D('lace',{etymology:E('Lace entered English through Old French forms for a cord or netted fabric; it can name decorative openwork cloth or a cord, and it is also a verb for fastening or adding a small ingredient to a drink.','lace'),contexts:[C('lace.s2','日常穿着','Before the race, the runner tightened each shoe lace and double-knotted it so it would not come loose.','比赛前，跑步者系紧每只鞋的鞋带并打了双结，以免松开。','Before the race / the runner tightened each shoe lace / and double-knotted it / so it would not come loose.','lace.s2 指穿过孔洞、用于系紧衣物或鞋子的带子。','跑步者收紧鞋带并打结固定。')],mistakes:[M('The runner tightened the shoe lace by removing the cord from every eyelet and leaving the shoe completely unfastened.','The runner tightened the shoe lace by pulling the cord through the eyelets and tying it.','抽出鞋带会让鞋子松开，不是系紧。')],quiz:[Q('lace',1,1,'Lace as a fabric is?','fine cloth with an open decorative pattern','a solid sheet of metal','a type of laboratory record','fine cloth with an open decorative pattern','lace.s1 指网眼状装饰布料。'),Q('lace',2,2,'A shoe lace is used to?','pull the shoe edges together through holes','decorate a flower’s petal','measure a muscle contraction','pull the shoe edges together through holes','lace.s2 指用来系紧鞋子的带子。'),Q('lace',3,3,'To lace a boot is to?','fasten it by tightening its cord','add a metal alloy to it','publish a magazine issue','fasten it by tightening its cord','lace.s3 作动词表示穿带并系紧。'),Q('lace',4,4,'To lace a drink with rum is to?','add a small amount of rum to it','tie a cord around the glass','remove every flavor from it','add a small amount of rum to it','lace.s4 指在饮料中掺入少量酒或调料。')]});
D('lacerate',{etymology:E('Lacerate comes from Latin lacerare “to tear”; it can mean tear skin or flesh roughly, or cause severe emotional distress.','lacerate'),contexts:[C('lacerate.s2','情感描写','The reviewer’s personal attack seemed to lacerate the young author, who left the room in tears.','评论者的人身攻击似乎深深伤害了年轻作者，她含泪离开了房间。','The reviewer’s personal attack / seemed to lacerate the young author / who left the room / in tears.','lacerate.s2 比喻严重伤害某人的感情。','人身攻击令作者痛苦落泪，体现情感上的撕裂。')],mistakes:[M('The gentle, respectful feedback lacerated the writer emotionally even though it praised her work and caused no distress.','The cruel personal insult lacerated the writer emotionally and left her visibly upset.','赞扬且没有造成痛苦的反馈不属于严重情感伤害。')],quiz:[Q('lacerate',1,1,'To lacerate skin is to?','cut or tear it roughly','wash it gently with water','cover it with lace','cut or tear it roughly','lacerate.s1 指划破或撕裂皮肉。'),Q('lacerate',2,2,'A cruel remark may lacerate someone by?','causing severe emotional pain','making the person feel rested','helping the person find a route','causing severe emotional pain','lacerate.s2 可比喻严重伤害感情。'),Q('lacerate',3,1,'Which injury could be described as lacerated?','flesh torn by a sharp edge','skin untouched by any object','a bruise with no broken skin only','flesh torn by a sharp edge','锐器撕裂皮肉属于 laceration。'),Q('lacerate',4,1,'Lacerate is closest to?','tear','decorate','irrigate','tear','tear 可表达撕裂，与 lacerate.s1 接近。','confusable')]});
D('lack',{etymology:E('Lack is recorded in Middle English as a verb meaning to be without; its precise earlier origin is uncertain. It is used as both a noun and a verb.','lack'),contexts:[C('lack.s2','项目管理','The project lacks a clear maintenance plan, so the team assigned an engineer to prepare one before launch.','该项目缺少明确的维护计划，因此团队指派一名工程师在发布前拟定计划。','The project lacks a clear maintenance plan / so the team assigned an engineer / to prepare one / before launch.','lack.s2 作动词，表示没有或不足；宾语通常是缺少的事物。','项目没有维护计划，团队需要补上。')],mistakes:[M('The plan lacked detail because it specified every task, owner, date, and contingency in full.','The plan lacked detail because it named no tasks, owners, dates, or contingencies.','内容详尽与“缺少细节”矛盾。')],quiz:[Q('lack',1,1,'A lack of evidence means?','not enough evidence is available','evidence has been fully confirmed','a document was officially issued','not enough evidence is available','lack.s1 指缺少或不足。'),Q('lack',2,2,'If a project lacks a schedule, it?','does not have one','has a complete timetable','has an extra ladder','does not have one','lack.s2 作动词表示没有。'),Q('lack',3,3,'“The argument lacks clarity” means it?','is not clear enough','is perfectly clear','contains a magazine edition','is not clear enough','lack.s3 表示缺少预期品质，此处为清晰度。'),Q('lack',4,2,'Which sentence uses lack as a verb?','The report lacks reliable sources.','A lack of sleep made him tired.','The ladder has three rungs.','The report lacks reliable sources.','此处 lack 后接宾语，作动词“缺少”。','grammar')]});
D('lackey',{etymology:E('Lackey came into English through French laquais, originally a footman; it now commonly means a servile follower or flatterer and can be used as a verb for serving obsequiously.','lackey'),contexts:[C('lackey.s1','政治讽刺','The columnist called the official a lackey for repeating the minister’s views without questioning the evidence.','专栏作者称这名官员为走狗，因为他不质疑证据便重复部长的观点。','The columnist called the official a lackey / for repeating the minister’s views / without questioning / the evidence.','lackey.s1 指对有权势者唯命是从、奉承逢迎的人，常含贬义。','官员不加审查地附和上级，显得盲从。')],mistakes:[M('The article called the independent inspector a lackey even though she publicly challenged the minister and reported the contrary evidence.','The article called the aide a lackey because he praised the minister and obeyed every order without question.','公开质疑上级并报告相反证据，不是唯命是从。')],quiz:[Q('lackey',1,1,'A lackey is usually?','a servile follower of a powerful person','an impartial investigator','a worker who repairs ladders','a servile follower of a powerful person','lackey.s1 是带贬义的盲从者或奉承者。'),Q('lackey',2,2,'To lackey for a boss is to?','wait on or flatter the boss servilely','challenge every decision independently','publish an official report','wait on or flatter the boss servilely','lackey.s2 作动词指卑躬屈膝地侍候或奉承。'),Q('lackey',3,1,'Which person is most likely called a lackey?','an aide who echoes a leader without independent judgment','an auditor who reports evidence against a leader','a visitor who asks for directions','an aide who echoes a leader without independent judgment','缺乏独立判断地附和领袖，符合贬义用法。'),Q('lackey',4,1,'Calling someone a lackey usually expresses?','disapproval of servile loyalty','praise for careful scientific work','a neutral job title for every assistant','disapproval of servile loyalty','lackey 通常带有贬义。','register')]});
D('lacking',{etymology:E('Lacking is the present participle of lack and an adjective meaning not having enough of something necessary or expected.','lacking'),contexts:[C('lacking.s1','文章评估','The draft was strong on examples but lacking in evidence for its central claim.','这份草稿的例子很充分，但支撑核心论点的证据不足。','The draft was strong on examples / but lacking in evidence / for its central claim.','lacking 常与 in 连用，表示缺少某种必要成分或品质。','文章缺乏支持核心观点的证据。')],mistakes:[M('The report was lacking in evidence because it included dozens of independently verified measurements and cited every source.','The report was lacking in evidence because it offered a claim without measurements or sources.','大量核实数据和完整来源说明并非缺乏证据。')],quiz:[Q('lacking',1,1,'A report lacking in evidence?','does not have enough supporting evidence','contains more evidence than needed','has been officially issued','does not have enough supporting evidence','lacking 表示缺少、不足。'),Q('lacking',2,1,'Which phrase is natural?','lacking in detail','lacking of detail','lacking by detail','lacking in detail','常见结构为 lacking in + 缺少的内容。','collocation'),Q('lacking',3,1,'A draft is lacking in clarity if it?','is difficult to understand','explains each point clearly','contains no words at all','is difficult to understand','缺乏清晰度意味着难以理解。'),Q('lacking',4,1,'Lacking is closest to?','deficient in','full of','iridescent','deficient in','deficient in 可表示缺乏。','confusable')]});
D('lacquer',{etymology:E('Lacquer entered English through European forms related to lac, a resinous material; it names a hard glossy coating and the verb for applying that coating.','lacquer'),contexts:[C('lacquer.s2','木器修复','The craftsperson will lacquer the wooden box in several thin coats and let each layer dry before polishing it.','工匠会给木盒涂上几层薄漆，每层干透后再打磨。','The craftsperson will lacquer the wooden box / in several thin coats / and let each layer dry / before polishing it.','lacquer.s2 作动词，表示在表面涂漆或涂上清漆。','分层涂布并干燥后抛光，是表面涂漆工序。')],mistakes:[M('The craftsperson lacquered the box by leaving the wood completely bare and applying no coating.','The craftsperson lacquered the box by applying and drying a glossy protective coat.','未涂任何涂层就没有 lacquer。')],quiz:[Q('lacquer',1,1,'Lacquer as a noun is?','a liquid coating that dries hard and shiny','an empty place in a manuscript','a game played with a netted stick','a liquid coating that dries hard and shiny','lacquer.s1 指干燥后形成硬而亮表面的漆。'),Q('lacquer',2,2,'To lacquer a cabinet is to?','cover it with a lacquer coating','remove every finish from it','load it onto a ship','cover it with a lacquer coating','lacquer.s2 作动词表示涂漆。'),Q('lacquer',3,2,'Which action is lacquering?','applying thin glossy coats to a wooden box','washing a wound with saline','measuring an orchid petal','applying thin glossy coats to a wooden box','涂上光亮涂层属于 lacquer。'),Q('lacquer',4,1,'A lacquer finish is often?','hard and glossy','soft and invisible','irregularly shaped','hard and glossy','漆膜干燥后通常坚硬光亮。')]});
D('lacrosse',{etymology:E('Lacrosse comes from French la crosse, “the stick,” referring to the long-handled implement used in the game; it is a team sport played with a netted stick.','lacrosse'),contexts:[C('lacrosse.s1','校园体育','The lacrosse team practiced passing with the netted sticks before playing its regional semifinal.','长曲棍球队在参加地区半决赛前练习用网兜球杆传球。','The lacrosse team practiced passing / with the netted sticks / before playing / its regional semifinal.','lacrosse 是用长柄网兜球杆进行的团队运动。','队员用球杆传球是长曲棍球训练。')],mistakes:[M('The coach called the match lacrosse even though players used no sticks and competed only by swimming underwater.','The coach called the match lacrosse because players passed and carried the ball with netted sticks.','没有球杆且只进行水下游泳，不是长曲棍球比赛。')],quiz:[Q('lacrosse',1,1,'Lacrosse is played using?','a long stick with a small net','only a wooden ladder','a sealed laboratory tube','a long stick with a small net','长曲棍球使用带网兜的长球杆。'),Q('lacrosse',2,1,'Which scene shows lacrosse?','players pass a ball with netted sticks on a field','players row boats across a lagoon','workers apply lacquer to a cabinet','players pass a ball with netted sticks on a field','用网兜球杆传球的队伍在打长曲棍球。'),Q('lacrosse',3,1,'The name lacrosse is associated with the game’s?','stick','island','invoice','stick','其名称来自法语中表示球杆的词。','word-formation'),Q('lacrosse',4,1,'Lacrosse is usually a?','team sport','form of medical isolation','type of magazine issue','team sport','长曲棍球是团队运动。')]});
D('lacuna',{etymology:E('Lacuna comes from Latin lacuna “hole or gap”; it can name a blank in a manuscript or a missing part in knowledge, evidence, or law.','lacuna'),contexts:[C('lacuna.s1','文献研究','A lacuna in the manuscript interrupts the final sentence, where two lines have been lost from the damaged page.','手稿中有一处空白，受损纸页丢失的两行使最后一句中断。','A lacuna in the manuscript interrupts the final sentence / where two lines / have been lost / from the damaged page.','lacuna 指手稿中的空白缺文，也可比喻知识、证据或法律中的空缺。','文本缺失两行，留下了可见的缺文。')],mistakes:[M('The editor marked a lacuna where every word remained intact and no part of the manuscript was missing.','The editor marked a lacuna where water damage had erased two lines of text.','内容完整无缺时不应标出缺文。')],quiz:[Q('lacuna',1,1,'A lacuna in a manuscript is?','a gap where text is missing','a decorative border around every page','a complete index of the book','a gap where text is missing','lacuna.s1 指手稿中的缺文或空白。'),Q('lacuna',2,1,'A lacuna in the evidence means?','an important missing part of the evidence','a fully documented fact','a shiny coating on a surface','an important missing part of the evidence','lacuna 也比喻证据中的空缺。'),Q('lacuna',3,1,'Which finding reveals a lacuna?','two lines have disappeared from the damaged page','every line is legible and complete','a reader has tied the book closed','two lines have disappeared from the damaged page','纸页上两行文字缺失形成空白。'),Q('lacuna',4,1,'Lacuna is closest to?','gap','ladder','laborer','gap','gap 与 lacuna 的“空缺”义相近。','confusable')]});
D('lad',{etymology:E('Lad is recorded in Middle English for a boy or young man; its earlier origin is uncertain. In informal British usage it can also address male friends.','lad'),contexts:[C('lad.s1','校园生活','The young lad helped his grandfather carry the groceries from the car to the kitchen.','这个小伙子帮爷爷把杂货从车里搬进厨房。','The young lad helped his grandfather / carry the groceries / from the car / to the kitchen.','lad.s1 指男孩或年轻男子，常见于非正式用语。','young lad 表示年轻小伙子。')],mistakes:[M('The report called an elderly woman a lad in the ordinary sense of the word, despite the term’s usual reference to a boy or young man.','The report called the teenage boy a lad.','lad 通常指男孩或年轻男子，不是对老年女性的普通称呼。')],quiz:[Q('lad',1,1,'A lad is usually?','a boy or young man','a small island','a ship’s left side','a boy or young man','lad.s1 指男孩或年轻男子。'),Q('lad',2,2,'Among some male friends, “lads” can be used as?','an informal form of address','a scientific name for an orchid petal','a formal court order','an informal form of address','lad.s2 可在男性朋友间作非正式称呼。'),Q('lad',3,1,'Which person could naturally be called a lad?','a teenage boy carrying groceries','a mature orchid flower','a magazine edition','a teenage boy carrying groceries','teenage boy 属于 lad 常见指称范围。'),Q('lad',4,1,'Lad is an informal word for?','a young male person','a lacquered surface','a labor-saving appliance','a young male person','lad 的常用义是男孩或小伙子。')]});
D('ladder',{etymology:E('Ladder comes from Old English hlæder; it can mean climbing equipment, a ranked series or route of advancement, or a long run in a stocking.','ladder'),contexts:[C('ladder.s3','衣物修补','A ladder appeared in the runner’s tights when one broken thread began to unravel in a long vertical line.','跑步者的紧身裤上出现了一道抽丝，一根断线开始沿纵向脱散。','A ladder appeared in the runner’s tights / when one broken thread / began to unravel / in a long vertical line.','ladder.s3 指长袜或针织衣物中由线圈脱散形成的长条破口。','一根线断裂后，针织结构沿直线脱散。')],mistakes:[M('The tights had a ladder even though every thread remained intact and the fabric had no run or opening.','The tights had a ladder where a broken thread had unraveled into a long opening.','没有线圈脱散或破口，就没有衣物抽丝。')],quiz:[Q('ladder',1,1,'A ladder used by a painter is?','equipment with sides and rungs for climbing','a series of magazine editions','a shiny coating','equipment with sides and rungs for climbing','ladder.s1 指供人攀爬的梯子。'),Q('ladder',2,2,'A career ladder is?','a sequence of stages for advancement','a tool used to reach a roof','a small island','a sequence of stages for advancement','ladder.s2 比喻晋升阶梯或等级序列。'),Q('ladder',3,3,'A ladder in tights is?','a long run caused by broken threads','a wooden climbing frame','a job promotion','a long run caused by broken threads','ladder.s3 指针织衣物抽丝。'),Q('ladder',4,1,'Which item has rungs for climbing?','a ladder','a lacuna','a labellum','a ladder','梯子的横档供人攀爬。')]});
D('lade',{etymology:E('Lade comes from Old English hladan “to load”; it is a somewhat formal or nautical verb meaning put cargo into a ship or container.','lade'),contexts:[C('lade.s1','港口作业','Dockworkers will lade the grain onto the vessel after the cargo hold has been inspected.','货舱检查完毕后，码头工人将把谷物装上船。','Dockworkers will lade the grain onto the vessel / after the cargo hold / has been inspected.','lade 指把货物装到船上或装入容器，带有正式或航海色彩。','谷物被装载到货船中。')],mistakes:[M('They lade the cargo onto the vessel yesterday.','They laded the cargo onto the vessel yesterday.','lade 的过去式是 laded，而不是原形 lade。','verb-form')],quiz:[Q('lade',1,1,'To lade a ship is to?','put cargo aboard it','unload every passenger only','repair a ladder','put cargo aboard it','lade.s1 指装货上船。'),Q('lade',2,1,'Which action is lading?','loading crates into a vessel’s hold','painting a cabinet with lacquer','measuring a flower petal','loading crates into a vessel’s hold','把货箱装入船舱是装载。'),Q('lade',3,1,'Lade is most likely to appear in a?','formal or nautical context','casual recipe for salad','description of a small boy only','formal or nautical context','lade 是较正式或航海用语。','register'),Q('lade',4,1,'Choose the correct past form: “They ___ the cargo yesterday.”','laded','ladded','lading','laded','lade 的过去式为 laded。','verb-form')]});
D('laden',{etymology:E('Laden is the past participle of lade and also an adjective meaning carrying a load or full of a feeling, quality, or meaning.','laden'),contexts:[C('laden.s2','文学分析','Her farewell was laden with regret, although she smiled and wished the departing crew a safe journey.','她的告别话语充满遗憾，尽管她微笑着祝离开的船员一路平安。','Her farewell was laden with regret / although she smiled / and wished the departing crew / a safe journey.','laden.s2 常用于 laden with，表示充满某种情绪、意味或特质。','regret 说明告别话语中充满遗憾。')],mistakes:[M('The farewell was laden with joy because it contained no happiness, warmth, or positive feeling.','The farewell was laden with joy because the speaker celebrated the crew’s safe return.','没有快乐或积极感受，不能说充满喜悦。')],quiz:[Q('laden',1,1,'A cart laden with boxes is?','carrying a heavy load','completely empty','made of lace','carrying a heavy load','laden.s1 指满载某物的。'),Q('laden',2,2,'A speech laden with sadness is?','full of sadness','free of emotion','a ship’s cargo list','full of sadness','laden.s2 比喻充满某种情绪。'),Q('laden',3,2,'Which phrase uses the figurative sense?','a warning laden with political meaning','a ladder laden with boxes','a bird with empty claws','a warning laden with political meaning','警告中含有大量政治意味，是比喻用法。'),Q('laden',4,1,'The past participle of lade is?','laden','laded only','ladder','laden','laden 是 lade 的过去分词，也可作形容词。','verb-form')]});
D('ladle',{etymology:E('Ladle comes from Old English hlædel, a utensil for dipping or serving liquid; it is also the verb for scooping or serving with one.','ladle'),contexts:[C('ladle.s1','厨房服务','Mina used a long-handled ladle to portion the vegetable soup into bowls without spilling it.','米娜用长柄勺把蔬菜汤分到碗里，没有洒出来。','Mina used a long-handled ladle / to portion the vegetable soup / into bowls / without spilling it.','ladle 可作名词指长柄勺，也可作动词表示用勺舀取或分盛。','长柄勺用于从锅中舀汤并分到碗里。')],mistakes:[M('The cook ladled the soup by pouring it from the pot with no scoop or serving utensil.','The cook ladled the soup into bowls with a long-handled serving spoon.','没有用勺舀取时不宜说 ladle the soup。')],quiz:[Q('ladle',1,1,'A ladle is a?','long-handled spoon for serving soup','small ladder for climbing','thin decorative fabric','long-handled spoon for serving soup','ladle.s1 可指长柄盛汤勺。'),Q('ladle',2,1,'To ladle soup is to?','scoop or serve it with a spoon','cover it with lacquer','leave it in a lair','scoop or serve it with a spoon','ladle 作动词表示用勺舀取或分盛。'),Q('ladle',3,1,'Which tool would a cook use to ladle stew?','a deep serving spoon with a handle','a paper lampshade','a kymograph','a deep serving spoon with a handle','深柄盛汤勺适合舀取炖菜。'),Q('ladle',4,1,'“She ladled gravy over the potatoes” means she?','scooped and poured gravy onto them','tied them with a lace','made them into a layer','scooped and poured gravy onto them','ladle 表示用勺舀浇。')]});
D('lady',{etymology:E('Lady developed from Old English hlæfdige, historically a title of status; modern uses include a polite term for a woman, a title, and the phrase the ladies for a women’s toilet.','lady'),contexts:[C('lady.s1','礼貌称呼','A lady near the station asked the conductor whether the next train stopped at the university.','车站附近的一位女士问列车员，下一班车是否停靠大学站。','A lady near the station asked the conductor / whether the next train / stopped / at the university.','lady.s1 是礼貌称呼女性的词；具体场合仍应尊重当事人偏好。','句中 lady 指向列车员问路的女性。')],mistakes:[M('The announcement addressed every woman as “lady” despite knowing the group had asked to be called by another term.','The announcement politely addressed the visitor as a lady after using the form of address she preferred.','礼貌用语应考虑对象的偏好，不应无视明确要求。')],quiz:[Q('lady',1,1,'In “A lady asked for directions,” lady means?','a woman, referred to politely','a young lamb','a type of lamp','a woman, referred to politely','lady.s1 可礼貌地指一位女性。'),Q('lady',2,2,'“Lady Chen” may use lady as?','a title before a name','a verb meaning to climb','a word for a lagoon','a title before a name','lady.s2 可作身份称号或置于姓名前。'),Q('lady',3,3,'In “Where are the ladies?” the phrase can refer to?','the women’s public toilet','a formal group of clergy','a ladder’s rungs','the women’s public toilet','the ladies 可委婉指女厕所。'),Q('lady',4,1,'Which is a polite use of lady?','A lady in the waiting room asked a question.','The ladybug climbed onto the plant.','The lamp became a lady.','A lady in the waiting room asked a question.','此处 lady 以礼貌方式指女性。')]});
D('ladybug',{etymology:E('Ladybug combines lady and bug; its traditional English name refers to the small spotted beetle, which gardeners value because it eats aphids.','ladybug'),contexts:[C('ladybug.s1','花园观察','A ladybug crawled across the bean leaves and fed on the aphids clustered around the new shoots.','一只瓢虫爬过豆叶，吃掉了聚集在新芽周围的蚜虫。','A ladybug crawled across the bean leaves / and fed on the aphids / clustered around / the new shoots.','ladybug 指常有斑点、以蚜虫为食的小型甲虫。','瓢虫捕食豆苗上的蚜虫，是园艺中的益虫。')],mistakes:[M('The gardener identified the smooth green caterpillar as a ladybug even though it had no beetle body or spotted wing covers.','The gardener identified the small spotted beetle feeding on aphids as a ladybug.','毛虫不是瓢虫；该词指一种小型甲虫。')],quiz:[Q('ladybug',1,1,'A ladybug is a small?','spotted beetle','young sheep','long-handled spoon','spotted beetle','ladybug 指小型斑点甲虫。'),Q('ladybug',2,1,'Gardeners often welcome ladybugs because they eat?','aphids','orchid petals','wooden ladders','aphids','瓢虫常捕食危害植物的蚜虫。'),Q('ladybug',3,1,'Which sighting is a ladybug?','a spotted beetle moving among leaves','a lamb resting beside a fence','a frog swimming in a lagoon','a spotted beetle moving among leaves','叶片上的斑点甲虫是瓢虫。'),Q('ladybug',4,1,'Ladybug is a common name for an insect in the?','beetle group','sheep family','fungus family','beetle group','瓢虫属于甲虫。')]});
D('lag',{etymology:E('Lag comes from a word meaning to fall behind; it also names a delay and is used in a separate technical verb meaning cover a pipe or tank with insulation.','lag'),contexts:[C('lag.s2','网络连接','The video call had a two-second lag, so each speaker heard replies well after the other person had finished.','视频通话有两秒延迟，因此每位说话者都在对方说完后很久才听到回复。','The video call had a two-second lag / so each speaker heard replies / well after / the other person had finished.','lag.s2 指一个事件与相关后续事件之间的时间差或延迟。','声音传输晚于说话发生，形成两秒时滞。')],mistakes:[M('The signal had a lag of zero seconds because every reply arrived before the other person spoke.','The signal had a lag of two seconds because replies arrived after the speech.','零延迟且提前收到回复，与存在两秒时滞矛盾。')],quiz:[Q('lag',1,1,'If one runner lags behind, the runner?','falls behind the others','finishes first','covers a pipe with insulation','falls behind the others','lag.s1 作动词表示落后。'),Q('lag',2,2,'A two-second signal lag is?','a two-second delay','a two-second head start','a type of beetle','a two-second delay','lag.s2 是时间延迟。'),Q('lag',3,3,'To lag a pipe is to?','cover it with insulation to reduce heat loss','load it onto a ship','make a map of its route','cover it with insulation to reduce heat loss','lag.s3 是给管道加保温层。'),Q('lag',4,2,'Which example has a lag?','a message arrives several seconds after it was sent','a message arrives instantly','a pipe is wrapped in insulation','a message arrives several seconds after it was sent','发送与收到之间的间隔就是延迟。')]});
D('lagoon',{etymology:E('Lagoon comes through Italian laguna and Spanish laguna from Latin lacuna “pool or hollow”; it refers to shallow water beside or partly separated from the sea.','lagoon'),contexts:[C('lagoon.s1','海岸生态','A narrow sandbar sheltered the lagoon, where juvenile fish fed in the calm, shallow water.','一条狭长沙洲挡住了海湾泻湖，小鱼在平静的浅水中觅食。','A narrow sandbar sheltered the lagoon / where juvenile fish fed / in the calm / shallow water.','lagoon.s1 指靠近海边、与海相连或被隔开的浅咸水区。','沙洲保护着近海浅水，形成泻湖环境。')],mistakes:[M('The map labeled a deep freshwater lake hundreds of miles inland a lagoon even though it had no coastal connection.','The map labeled the shallow coastal pool behind a sandbar a lagoon.','远离海岸的深水淡水湖不符合此处 lagoon 的常见地貌义。')],quiz:[Q('lagoon',1,1,'A lagoon is often?','shallow water near or partly separated from the sea','a deep cave far underground','a machine for tracing pulse waves','shallow water near or partly separated from the sea','lagoon.s1 常指近海浅水区或泻湖。'),Q('lagoon',2,2,'A coastal lagoon may be?','a shallow stretch of water near the shore','a mountain peak far inland','a building used for experiments','a shallow stretch of water near the shore','lagoon.s2 也可泛指近海浅水区。'),Q('lagoon',3,1,'A sandbar can help form a lagoon by?','sheltering shallow water beside the sea','drying every river in a region','covering a metal surface with lacquer','sheltering shallow water beside the sea','沙洲可挡住海水，围出浅水区。'),Q('lagoon',4,1,'Which location is most likely a lagoon?','a calm shallow pool behind a coastal sandbar','a deep reservoir in a mountain tunnel','a laboratory wash basin','a calm shallow pool behind a coastal sandbar','海岸沙洲后的浅水池符合泻湖特征。')]});
D('laid off',{etymology:E('Laid off is the past-tense or participial form of the phrasal verb lay off; in employment it means an employer ended someone’s job, usually for business reasons.','laid off'),contexts:[C('laid off.s1','职场变动','After the factory lost its largest contract, forty workers were laid off even though their performance reviews were strong.','工厂失去最大的一份合同后，尽管员工绩效评估良好，仍有四十人被裁员。','After the factory lost its largest contract / forty workers were laid off / even though / their performance reviews were strong.','laid off 指雇主因业务原因停止雇用某人；通常并非因员工失职。','合同流失造成岗位削减，绩效良好者也失去工作。')],mistakes:[M('The company laid off the employee as a reward for promotion and immediately raised her salary.','The company laid off the employee when it closed the department and removed her position.','裁员意味着结束雇用，不是升职加薪。')],quiz:[Q('laid off',1,1,'A worker who is laid off has?','lost the job because the employer ended the position','resigned to take a better job voluntarily','received a promotion','lost the job because the employer ended the position','laid off 表示被雇主裁撤岗位。'),Q('laid off',2,1,'Which situation may lead workers to be laid off?','a company closes a department after losing business','an employee receives an annual award','a worker starts a scheduled vacation','a company closes a department after losing business','业务萎缩或部门关闭可能导致裁员。'),Q('laid off',3,1,'“Several staff were laid off” is closest to?','several staff lost their jobs through employer action','several staff were promoted','several staff were asked to work overtime','several staff lost their jobs through employer action','雇主结束雇用关系意味着员工被裁。'),Q('laid off',4,1,'Being laid off necessarily means the worker performed badly?','no; a position may be cut for business reasons','yes; it always proves misconduct','yes; it means the person resigned','no; a position may be cut for business reasons','裁员可由企业经营原因引起，与个人表现不必相关。','distinction')]});
D('laid-back',{etymology:E('Laid-back combines the participle laid with back; as an informal adjective it describes someone or an atmosphere that is calm and relaxed.','laid-back'),contexts:[C('laid-back.s1','人物描写','Our laid-back guide let the group explore the old town at its own pace and never hurried anyone.','我们这位悠闲的导游让大家按自己的节奏逛老城区，从不催促任何人。','Our laid-back guide let the group explore the old town / at its own pace / and never hurried anyone.','laid-back 是非正式形容词，表示从容、放松、不急躁的。','导游允许大家慢慢探索，态度轻松。')],mistakes:[M('The host was laid-back because she rushed every guest, shouted at delays, and demanded that dinner start early.','The host was laid-back because she let guests relax and adjusted the schedule without fuss.','不断催促并因延误发火与 laid-back 的放松态度相反。')],quiz:[Q('laid-back',1,1,'A laid-back person is?','calm and relaxed','strictly hurried','a small island','calm and relaxed','laid-back 指悠闲放松的。'),Q('laid-back',2,1,'Which atmosphere is laid-back?','a café where no one rushes the guests','an office where every minute is shouted over','a test room under strict timing','a café where no one rushes the guests','不催促、节奏轻松的咖啡馆氛围很 laid-back。'),Q('laid-back',3,1,'Laid-back is an informal?','adjective','noun for a laboratory','verb meaning to coat with lacquer','adjective','laid-back 作形容词。','word-formation'),Q('laid-back',4,1,'The opposite of a laid-back schedule is a?','hectic, tightly pressured schedule','quiet and flexible plan','slow, unhurried afternoon','hectic, tightly pressured schedule','紧张匆忙的安排与 laid-back 相反。','confusable')]});
D('lair',{etymology:E('Lair comes from Old English leger, “place to lie down”; it names the den or resting place of a wild animal.','lair'),contexts:[C('lair.s1','野生动物调查','The field team found fresh tracks leading from the deer’s lair to a stream at the edge of the forest.','野外小组发现新鲜脚印从鹿的兽穴延伸到森林边缘的一条溪流。','The field team found fresh tracks / leading from the deer’s lair / to a stream / at the edge of the forest.','lair 指野生动物休息或藏身的兽穴、巢穴。','动物足迹从藏身处通向水源。')],mistakes:[M('The hikers called the crowded visitor center a wolf’s lair even though no animal rested or hid there.','The hikers called the sheltered cave where the wolf rested its lair.','供游客使用的中心不是野生动物的藏身处。')],quiz:[Q('lair',1,1,'A wild animal’s lair is its?','place to rest or hide','food supply','group of young','place to rest or hide','lair 指动物休息或躲藏的地方。'),Q('lair',2,1,'Which place could be a fox’s lair?','a sheltered den where it sleeps','a bright public ticket office','a shallow coastal lagoon','a sheltered den where it sleeps','兽穴为狐狸提供隐蔽和休息处。'),Q('lair',3,1,'Tracks leading from a lair may show where an animal?','went to find water or food','received a promotion','was laid off','went to find water or food','足迹可显示动物离开藏身处后的去向。'),Q('lair',4,1,'Lair is closest in meaning to?','den','ladle','lamina','den','den 同样指动物巢穴或兽穴。','confusable')]});
D('laissez-faire',{etymology:E('Laissez-faire is borrowed from French laissez faire, literally “let do”; it names a policy of limited interference and can describe an approach that avoids setting rules.','laissez-faire'),contexts:[C('laissez-faire.s1','经济政策','The minister defended a laissez-faire approach, arguing that firms should set prices without routine government direction.','部长为自由放任的做法辩护，认为企业应在没有政府日常指挥的情况下自行定价。','The minister defended a laissez-faire approach / arguing that firms should set prices / without routine government direction.','laissez-faire.s1 指尽量不干预商业或经济活动的政策。','该政策主张让企业自行决定价格。')],mistakes:[M('The policy was laissez-faire because officials set every firm’s prices, production quotas, and daily staffing levels.','The policy was laissez-faire because officials generally left firms to make those decisions themselves.','政府直接规定所有经营细节，不是自由放任。')],quiz:[Q('laissez-faire',1,1,'A laissez-faire economic policy tends to?','limit government interference in trade','set every price by central order','ban private business entirely','limit government interference in trade','laissez-faire.s1 指尽量不干预市场的政策。'),Q('laissez-faire',2,2,'A laissez-faire manager is likely to?','avoid unnecessary rules or interference','control every minor action','require approval for each breath','avoid unnecessary rules or interference','laissez-faire.s2 可形容不爱干预或设规的管理方式。'),Q('laissez-faire',3,1,'Which policy is laissez-faire?','businesses make most routine pricing choices','government sets every shop’s daily prices','all trade is prohibited','businesses make most routine pricing choices','企业自行定价体现有限干预。'),Q('laissez-faire',4,1,'Laissez-faire is borrowed from?','French','Old English','Greek','French','该词是法语借词。','word-formation')]});
D('laity',{etymology:E('Laity comes through ecclesiastical Latin from Greek laikos “of the people”; it can mean church members who are not clergy or, more broadly, non-specialists.','laity'),contexts:[C('laity.s1','教会治理','The new safeguarding policy was discussed with the laity as well as the clergy before it was adopted.','新保护政策在通过前，既征求了神职人员的意见，也与平信徒进行了讨论。','The new safeguarding policy was discussed / with the laity / as well as the clergy / before it was adopted.','laity 指非神职人员的教会成员，也可泛指某领域的普通外行。','句中将 laity 与 clergy 对照，指普通信徒。')],mistakes:[M('The church referred to its ordained priests as the laity and the non-ordained members as the clergy.','The church referred to its non-ordained members as the laity and its ordained ministers as the clergy.','laity 与 clergy 的区分恰好相反。')],quiz:[Q('laity',1,1,'In a church, the laity are?','members who are not clergy','the ordained clergy only','people who design lamps','members who are not clergy','laity 指非神职人员的信徒。'),Q('laity',2,1,'Outside religion, the laity may mean?','ordinary people without specialist knowledge','a group of professional clergy','a species of beetle','ordinary people without specialist knowledge','laity 也可泛指非专业人士。'),Q('laity',3,1,'The clergy and the laity differ mainly in?','their religious role or ordination','their country of birth','the number of ladders they own','their religious role or ordination','laity 与 clergy 的区别在于是否为神职人员。'),Q('laity',4,1,'A museum may explain a technical topic for the laity by?','using language accessible to non-specialists','requiring advanced specialist credentials','speaking only in untranslated jargon','using language accessible to non-specialists','面向普通公众解释时应避免只用专业术语。')]});
D('lake',{etymology:E('Lake comes through Old French and Latin lacus “pool”; it can name a large natural inland body of water or an artificial body made for recreation or storage.','lake'),contexts:[C('lake.s2','公园规划','The new lake in the city park stores rainwater and gives visitors a place to walk beside the water.','城市公园里的人工湖储存雨水，也为游客提供沿水散步的地方。','The new lake in the city park / stores rainwater / and gives visitors / a place to walk beside the water.','lake.s2 指为公园或蓄水等用途人工修建的大面积水体。','该水体由公园规划建设并承担储水功能。')],mistakes:[M('The map called the artificial reservoir a natural lake even though engineers had built it to store water.','The map called the engineered reservoir an artificial lake.','由工程建造的水体不应说成天然湖泊。')],quiz:[Q('lake',1,1,'A lake is usually?','a large body of water surrounded by land','a stream that always flows into the sea','a shallow patch of bare soil','a large body of water surrounded by land','lake.s1 指四周被陆地环绕的大面积水域。'),Q('lake',2,2,'An artificial lake may be built to?','store water or provide recreation','serve as a climbing ladder','record a muscle contraction','store water or provide recreation','lake.s2 可为蓄水或休闲用途人工修建。'),Q('lake',3,1,'Which feature is most likely a lake?','inland water surrounded by land','a narrow path on a hillside','a line of broken threads in tights','inland water surrounded by land','内陆且被陆地环绕的水体符合湖泊定义。'),Q('lake',4,2,'A reservoir behind a dam is an example of?','an artificial lake','a lair','a labellum','an artificial lake','水坝后蓄水可形成水库式人工湖。')]});
D('lamb',{etymology:E('Lamb comes from Old English lamb; it names a young sheep, its meat, or affectionately a gentle person.','lamb'),contexts:[C('lamb.s2','餐厅菜单','The menu lists roast lamb with rosemary and potatoes as the main course for Sunday lunch.','菜单将迷迭香烤羊肉配土豆列为周日午餐主菜。','The menu lists roast lamb / with rosemary and potatoes / as the main course / for Sunday lunch.','lamb.s2 指羔羊肉，常用于菜名或食物语境。','菜单中的 roast lamb 是羊肉菜肴。')],mistakes:[M('The menu described the roast lamb as a live young sheep waiting in a field rather than meat prepared for a meal.','The menu described roast lamb as meat from a young sheep prepared for a meal.','菜肴中的 lamb 指肉，不是活羊。')],quiz:[Q('lamb',1,1,'A lamb is?','a young sheep','a small spotted beetle','a lamp cover','a young sheep','lamb.s1 指小羊或羊羔。'),Q('lamb',2,2,'On a menu, lamb usually means?','meat from a young sheep','a live animal in the field','a long-handled spoon','meat from a young sheep','lamb.s2 指羊羔肉。'),Q('lamb',3,3,'Calling a gentle child “a lamb” uses the word?','affectionately for a mild person','as a technical term for a lake','to describe a laborer','affectionately for a mild person','lamb.s3 可亲切地比喻温顺的人。'),Q('lamb',4,1,'A lamb grows into a?','sheep','ladybug','lagoon','sheep','lamb 是幼年绵羊。')]});
D('lambent',{etymology:E('Lambent comes from Latin lambere “to lick”; by metaphor it describes a soft light that seems to flicker gently over a surface.','lambent'),contexts:[C('lambent.s1','夜景描写','Lambent candlelight moved across the stone walls as the guests walked through the old hall.','客人们穿过古老大厅时，轻柔摇曳的烛光掠过石墙。','Lambent candlelight moved across the stone walls / as the guests walked / through the old hall.','lambent 描写柔和、轻轻摇曳或掠过表面的光。','烛光柔和地映在墙面上，呈现轻微闪烁。')],mistakes:[M('The author described the harsh, steady floodlight as lambent even though it dazzled everyone and did not flicker or soften.','The author described the gentle, flickering candlelight as lambent.','刺眼而强烈的稳定光线与柔和摇曳的 lambent 不符。')],quiz:[Q('lambent',1,1,'Lambent light is usually?','soft and gently flickering','harsh and blinding','completely absent','soft and gently flickering','lambent 指柔亮、轻轻摇曳的光。'),Q('lambent',2,1,'Which scene has lambent light?','small flames moving softly over a wall','a blinding searchlight held steadily in place','a room with no light','small flames moving softly over a wall','轻柔摇曳的火光符合 lambent。'),Q('lambent',3,1,'Lambent most often describes?','light','a worker’s job title','a lake’s size','light','该词常用于描写光线。'),Q('lambent',4,1,'Lambent is closest to?','softly glowing','irrevocable','lacking','softly glowing','softly glowing 接近 lambent 的柔和发光义。','confusable')]});
D('lame',{etymology:E('Lame comes from Old English lama; it can describe impaired walking, a weak argument or excuse, something poor or boring informally, or the act of causing a limp. Use for people with care because the disability sense can be offensive or outdated.','lame'),contexts:[C('lame.s2','论证评估','The reviewer rejected the excuse as lame because the driver had ignored two clear warning signs.','评论者认为这个借口站不住脚，因为司机忽视了两个明显警示牌。','The reviewer rejected the excuse as lame / because the driver had ignored / two clear warning signs.','lame.s2 口语中可表示借口或论点软弱、不可信。','司机违反了明确警示，借口缺乏说服力。')],mistakes:[M('The excuse was lame because it gave a detailed, verifiable account supported by photographs and independent witnesses.','The excuse was lame because it contradicted the driver’s own recorded route.','有详细可核实证据支持的解释并非明显站不住脚。')],quiz:[Q('lame',1,1,'In a traditional physical sense, lame describes someone who?','cannot walk normally because of an injured leg or foot','has an unusually strong argument','works in a laboratory','cannot walk normally because of an injured leg or foot','lame.s1 是旧式身体描述，用于人时可能冒犯，应谨慎。'),Q('lame',2,2,'A lame excuse is?','weak and unconvincing','supported by strong evidence','a light that flickers softly','weak and unconvincing','lame.s2 指站不住脚的借口。'),Q('lame',3,3,'In informal speech, a lame movie may be?','boring or poor in quality','medically unable to walk','a lake made by a dam','boring or poor in quality','lame.s3 可口语表示无聊或差劲。'),Q('lame',4,4,'To lame an animal means to?','injure it so it cannot walk normally','help it climb a ladder','cover it with a lampshade','injure it so it cannot walk normally','lame.s4 作动词表示使跛或致残。')]});
D('lament',{etymology:E('Lament comes from Latin lamentari “to wail or mourn”; it can mean express deep sorrow and can also name a song or speech of mourning.','lament'),contexts:[C('lament.s1','环境保护','Residents lamented the loss of the old wetlands after construction drained the marsh and displaced nesting birds.','施工排干沼泽并赶走筑巢鸟类后，居民哀叹旧湿地的消失。','Residents lamented the loss of the old wetlands / after construction drained the marsh / and displaced nesting birds.','lament 作动词表示因失去或不幸而深切哀叹；作名词可指哀歌或哀辞。','居民对湿地与栖息地的消失表达悲痛。')],mistakes:[M('Residents lamented the restored wetlands as a tragic loss even though the marsh had returned and bird numbers had recovered.','Residents lamented the drained wetlands because the habitat and its nesting birds had been lost.','湿地恢复且鸟类回归，并非值得哀叹的损失。')],quiz:[Q('lament',1,1,'To lament a loss is to?','express deep sorrow about it','celebrate it without reservation','measure its distance','express deep sorrow about it','lament.s1 指哀叹或深切惋惜。'),Q('lament',2,1,'A lament may also be?','a song or speech expressing grief','a tool for climbing','a new issue of a magazine','a song or speech expressing grief','lament 也可作名词指哀歌或哀辞。'),Q('lament',3,1,'Which sentence uses lament as a verb?','They lamented the destruction of the forest.','She bought a lament at the store.','The lamp lamented softly.','They lamented the destruction of the forest.','此处 lament 后接所惋惜的破坏，作动词。','word-formation'),Q('lament',4,1,'Lament is closest to?','mourn','ladle','lacerate','mourn','mourn 可表示哀悼，与 lament 接近。','confusable')]});
D('lamina',{etymology:E('Lamina comes from Latin lamina “thin plate or layer”; it names a thin sheet or layer of material, including in rock, metal, or anatomy.','lamina'),contexts:[C('lamina.s1','地质剖面','The geologist identified a thin lamina of dark sediment between two pale layers of sandstone.','地质学家在两层浅色砂岩之间辨认出一层薄薄的深色沉积物。','The geologist identified a thin lamina / of dark sediment / between two pale layers / of sandstone.','lamina 指岩石、金属或组织中的薄片、薄层。','沉积物形成夹在砂岩层之间的薄层。')],mistakes:[M('The geologist called the massive, unlayered block a lamina even though it contained no thin sheet or layer.','The geologist called the narrow sediment layer between the sandstone beds a lamina.','巨大且没有分层的整体不是薄层。')],quiz:[Q('lamina',1,1,'A lamina is?','a thin layer or sheet','a large body of water','a person who guards prisoners','a thin layer or sheet','lamina 指薄层或薄片。'),Q('lamina',2,1,'A geologist might find a lamina in?','a layered rock formation','a shoelace knot','a women’s restroom','a layered rock formation','岩层中可出现薄薄的沉积层。'),Q('lamina',3,1,'Which item is a lamina?','a thin sheet of metal','a thick solid boulder with no layers','a long-handled spoon','a thin sheet of metal','薄金属片可称 lamina。'),Q('lamina',4,1,'Lamina is closest in meaning to?','layer','lagoon','lamb','layer','layer 与 lamina 的薄层义相近。','confusable')]});
D('laminate',{etymology:E('Laminate comes from Latin lamina “thin plate”; as a verb it means bond or cover with thin layers, and as a noun it names a material made of bonded layers.','laminate'),contexts:[C('laminate.s1','证件保护','The clerk will laminate the emergency contact card in clear plastic so it can survive rain and repeated handling.','办事员会给紧急联系人卡覆上透明塑料膜，使其经得住雨水和反复拿取。','The clerk will laminate the emergency contact card / in clear plastic / so it can survive rain / and repeated handling.','laminate.s1 作动词，表示将薄层黏合或用塑料膜覆膜。','透明塑料膜保护卡片免受水和磨损。')],mistakes:[M('The clerk laminated the card by leaving it uncoated and exposed to rain and dirt.','The clerk laminated the card by sealing it between thin protective plastic layers.','未覆膜或加保护层不算 laminate。')],quiz:[Q('laminate',1,1,'To laminate a card is to?','seal it in a thin protective layer','tear it into pieces','place it inside a lake','seal it in a thin protective layer','laminate.s1 可表示给文件覆膜。'),Q('laminate',2,2,'A laminate countertop is made from?','layers bonded together','a single strand of lace','an animal’s lair','layers bonded together','laminate.s2 指由多层黏合形成的材料。'),Q('laminate',3,1,'Why laminate an emergency card?','to protect it from water and wear','to make its text disappear','to turn it into a metal isotope','to protect it from water and wear','覆膜可保护卡片免受潮湿和磨损。'),Q('laminate',4,1,'The verb laminate is related to the noun?','lamina, a thin layer','lag, a delay','lad, a boy','lamina, a thin layer','laminate 与表示薄层的 lamina 同源。','word-formation')]});
D('lamp',{etymology:E('Lamp comes through Latin and Greek lampas “torch”; it names a device that produces light and can also mean a small indicator light on equipment.','lamp'),contexts:[C('lamp.s2','设备维护','A red lamp on the control panel stayed lit, warning the technician that the filter needed replacement.','控制面板上的红色指示灯一直亮着，提醒技术员需要更换滤芯。','A red lamp on the control panel stayed lit / warning the technician / that the filter / needed replacement.','lamp.s2 指显示设备状态的小型指示灯。','红灯亮起表示滤芯需要更换。')],mistakes:[M('The warning lamp stayed dark while the machine’s manual said its red indicator was actively lit.','The warning lamp stayed lit to show that the machine needed inspection.','灯处于熄灭状态与指示灯亮起相矛盾。')],quiz:[Q('lamp',1,1,'A desk lamp is a device that?','produces light','measures a time delay','holds soup','produces light','lamp.s1 指照明设备。'),Q('lamp',2,2,'A warning lamp on a machine indicates?','a condition or status','the latest magazine issue','a place for sheep','a condition or status','lamp.s2 指示设备状态。'),Q('lamp',3,2,'Which light is a warning lamp?','a small red indicator showing overheating','a candle flame used for reading','sunlight entering a window','a small red indicator showing overheating','红色状态灯提示机器过热。'),Q('lamp',4,1,'A lampshade is fitted over a?','lamp','lagoon','ladder','lamp','lamp 是 lampshade 所遮盖的照明设备。','word-formation')]});
D('lampoon',{etymology:E('Lampoon entered English as a word for sharp satirical writing; its precise earlier derivation is uncertain, so no deeper root is asserted here.','lampoon'),contexts:[C('lampoon.s1','政治讽刺','The cartoonist lampooned the mayor’s expensive “cost-cutting” plan by drawing a golden shovel beside an empty budget box.','漫画家画了一把金铲子和空预算箱，讽刺市长昂贵的“削减成本”计划。','The cartoonist lampooned the mayor’s expensive “cost-cutting” plan / by drawing a golden shovel / beside an empty budget box.','lampoon 可作动词表示以讽刺作品嘲弄某人或某事，也可作名词指这类作品。','金铲子与空预算箱揭示计划的自相矛盾。')],mistakes:[M('The cartoon lampooned the mayor by praising every decision sincerely and avoiding any mockery or criticism.','The cartoon lampooned the mayor by ridiculing the costly plan through sharp visual satire.','真诚赞扬而没有嘲讽，不属于 lampoon。')],quiz:[Q('lampoon',1,1,'To lampoon a public figure is to?','mock or criticize them through satire','write a neutral weather report','coat their desk with lacquer','mock or criticize them through satire','lampoon.s1 作动词指讽刺、嘲弄。'),Q('lampoon',2,1,'A lampoon may be?','a satirical written or filmed attack','a factual timetable for a trip','a long-handled soup spoon','a satirical written or filmed attack','lampoon 也可作名词指讽刺作品。'),Q('lampoon',3,1,'Which work is a lampoon?','a comic sketch mocking a politician’s claim','a neutral transcript of a meeting','a guide to identifying orchids','a comic sketch mocking a politician’s claim','用喜剧短剧嘲弄政客的作品属于讽刺。'),Q('lampoon',4,1,'Lampoon is closest to?','satirize','lament','laminate','satirize','satirize 表示讽刺，接近 lampoon 的动词义。','confusable')]});
D('lampshade',{etymology:E('Lampshade combines lamp and shade; it names a cover fitted over or around a light to soften, direct, or shield its illumination.','lampshade'),contexts:[C('lampshade.s1','室内照明','The linen lampshade softened the bedside bulb and kept the light from shining directly into the reader’s eyes.','亚麻灯罩柔化了床头灯泡的亮度，避免光线直射读者眼睛。','The linen lampshade softened the bedside bulb / and kept the light / from shining directly / into the reader’s eyes.','lampshade 指罩在灯泡或灯具上的布、纸或玻璃罩。','灯罩柔化并遮挡了直射光。')],mistakes:[M('The lamp had a lampshade that exposed the bare bulb completely and did not cover or soften its light.','The lamp had a lampshade that covered the bulb and softened its light.','完全无遮盖的灯泡没有灯罩。')],quiz:[Q('lampshade',1,1,'A lampshade is a cover fitted over a?','lamp or bulb','lamb','lake','lamp or bulb','lampshade 是灯具或灯泡上的罩子。'),Q('lampshade',2,1,'A lampshade may help to?','soften or direct the light','load cargo onto a ship','keep an animal in its lair','soften or direct the light','灯罩可柔化或引导光线。'),Q('lampshade',3,1,'Which item is a lampshade?','a fabric cover around a bedside bulb','the electrical cord plugged into the wall','a ladder beside the bed','a fabric cover around a bedside bulb','围绕灯泡的布罩是 lampshade。'),Q('lampshade',4,1,'Lampshade combines lamp with?','shade','lacuna','lag','shade','该词由 lamp 和 shade 组成。','word-formation')]});
D('lance',{etymology:E('Lance comes through French from Latin lancea; it names a long spear and is also a verb for cutting or opening with a sharp instrument.','lance'),contexts:[C('lance.s1','中世纪史','The knight lowered his lance before the tournament began, keeping the blunt practice tip pointed away from the crowd.','比武开始前，骑士放低长矛，并让钝头练习矛尖朝向远离人群的方向。','The knight lowered his lance / before the tournament began / keeping the blunt practice tip / pointed away from the crowd.','lance.s1 指用于刺击的长矛，历史上常与骑士比武相关。','骑士在比赛前拿着长矛并控制矛尖方向。')],mistakes:[M('The museum labeled the knight’s short wooden spoon a lance even though it could not be used as a spear.','The museum labeled the knight’s long spear a lance.','勺子不是用于刺击的长矛。')],quiz:[Q('lance',1,1,'A lance is traditionally a?','long spear','serving spoon','paper lampshade','long spear','lance.s1 指长矛。'),Q('lance',2,1,'To lance a boil is to?','open it with a sharp instrument','cover it with lacquer','measure it with a kymograph','open it with a sharp instrument','lance 也可作动词表示用尖锐工具切开。'),Q('lance',3,1,'Which object is a lance?','a long pole with a pointed metal head','a flat lake surrounded by land','a netted stick for lacrosse','a long pole with a pointed metal head','带尖端的长杆可作长矛。'),Q('lance',4,1,'The verb lance is most likely to be used in a?','medical or surgical context','description of an orchid petal','discussion of a job promotion','medical or surgical context','医务人员可用尖锐器具切开脓肿。','context')]});
D('land',{etymology:E('Land comes from Old English land; it names earth rather than sea or air, owned or usable ground, or a country, and as a verb it can mean arrive, obtain, or end up somewhere.','land'),contexts:[C('land.s2','房产交易','The family bought a narrow strip of land beside the road and plans to build a small workshop there.','这家人在路边买了一条狭长地块，计划在那里建一间小作坊。','The family bought a narrow strip of land / beside the road / and plans to build / a small workshop there.','land.s2 指可拥有或使用的土地、地产。','购地并用于建造作坊，体现地产义。'),C('land.s3','书面表达','She returned to her native land after decades abroad.','她在海外生活数十年后回到了祖国。','She returned to her native land / after decades abroad.','land 在此指国家或祖国，通常见于书面表达或歌词。','native land 指某人的祖国。'),C('land.s4','航空交通','The pilot will land the aircraft on the longer runway because the crosswind is getting stronger.','由于侧风越来越强，飞行员将在较长的跑道上让飞机着陆。','The pilot will land the aircraft / on the longer runway / because the crosswind / is getting stronger.','land.s4 作动词表示飞机着陆、船靠岸或人到达地面。','飞机从空中降落到跑道。'),C('land.s5','职业发展','After six interviews, Mei finally landed the research position at the coastal institute.','经过六轮面试，梅终于获得了海岸研究所的研究职位。','After six interviews / Mei finally landed the research position / at the coastal institute.','land.s5 作动词口语中可表示成功获得工作、合同等。','她经过多轮面试成功拿到职位。'),C('land.s6','处境变化','A careless online purchase landed Omar in debt after unexpected fees were added to the bill.','一笔草率的网上购物让奥马尔陷入债务，账单上还加收了意外费用。','A careless online purchase landed Omar in debt / after unexpected fees / were added to the bill.','land.s6 可指使某人落入某种境地，常为不理想处境。','购物和额外费用使他陷入债务。')],mistakes:[M('The plane landed by climbing higher into the sky and never reaching the ground or runway.','The plane landed by descending onto the runway.','升空而非接触地面与着陆相反。')],quiz:[Q('land',1,1,'“The hikers walked over land” contrasts land with?','the sea or air','a magazine issue','an artificial lake only','the sea or air','land.s1 指与海洋或天空相对的陆地。'),Q('land',2,3,'“She landed a contract” means she?','successfully obtained it','fell into a lake','made it an island','successfully obtained it','land.s5 可表示成功得到合同。'),Q('land',3,4,'“The boat landed at the harbor” means it?','arrived at the shore','was sold as real estate','took off into the air','arrived at the shore','land.s4 也可指船靠岸或到达。'),Q('land',4,6,'“The mistake landed him in trouble” means it?','caused him to end up in trouble','gave him a piece of property','helped him get a job','caused him to end up in trouble','land.s6 表示使人陷入某种处境。')]});
D('land-dwelling',{etymology:E('Land-dwelling combines land and dwelling; it describes an animal or organism that lives on land rather than in water.','land-dwelling'),contexts:[C('land-dwelling.s1','动物分类','The land-dwelling tortoise returned to its burrow after feeding on leaves near the dry riverbed.','这只陆生乌龟在干涸河床附近吃过树叶后，回到了自己的洞穴。','The land-dwelling tortoise returned to its burrow / after feeding on leaves / near the dry riverbed.','land-dwelling 作形容词，指生活在陆地上的生物。','乌龟在陆地觅食并返回洞穴。')],mistakes:[M('The biologist called the fish land-dwelling even though it lived underwater and could not survive outside the water.','The biologist called the tortoise land-dwelling because it lived and fed on dry ground.','完全依赖水生存的鱼不是陆生动物。')],quiz:[Q('land-dwelling',1,1,'A land-dwelling animal lives?','on land','only below the sea','inside a lampshade','on land','land-dwelling 指生活在陆地上的。'),Q('land-dwelling',2,1,'Which creature is land-dwelling?','a tortoise that feeds on dry ground','a fish that lives underwater','a dolphin in open water','a tortoise that feeds on dry ground','在陆地生活的乌龟是陆生动物。'),Q('land-dwelling',3,1,'Land-dwelling contrasts with?','aquatic','irreparable','lambent','aquatic','aquatic 表示水生，与 land-dwelling 相对。','confusable'),Q('land-dwelling',4,1,'A land-dwelling bird might build its nest?','on a tree or on the ground','only beneath the ocean','inside a lake','on a tree or on the ground','陆生鸟类在陆地或树上筑巢。')]});
D('landfill',{etymology:E('Landfill combines land and fill; it names a site where waste is buried under layers of soil or other material.','landfill'),contexts:[C('landfill.s1','废物管理','The new landfill uses a sealed liner and drainage pipes to keep leaking liquid away from groundwater.','新填埋场使用密封衬层和排水管，防止渗漏液污染地下水。','The new landfill uses a sealed liner / and drainage pipes / to keep leaking liquid / away from groundwater.','landfill 指通过掩埋方式处理废弃物的场地。','衬层和排水系统用于控制填埋场渗漏。')],mistakes:[M('The town called its recycling center a landfill even though no waste was buried there and all materials were sorted for reuse.','The town called the site where refuse was buried under soil a landfill.','只分类回收而不掩埋废物的中心不是 landfill。')],quiz:[Q('landfill',1,1,'A landfill is a place where waste is?','buried under the ground','stored in a museum display','turned into a travel itinerary','buried under the ground','landfill 指垃圾填埋场。'),Q('landfill',2,1,'Why might a landfill use a sealed liner?','to keep leaking waste liquid from reaching groundwater','to help land-dwelling birds migrate','to make a lake deeper','to keep leaking waste liquid from reaching groundwater','衬层有助于阻止渗滤液污染地下水。'),Q('landfill',3,1,'Which site is a landfill?','a facility that buries waste beneath soil','a plant that sorts all items for reuse only','a natural hillside with no waste disposal','a facility that buries waste beneath soil','掩埋废物的场地属于填埋场。'),Q('landfill',4,1,'Landfill combines land with?','fill','lamb','lace','fill','landfill 是 land 与 fill 组成的复合词。','word-formation')]});
D('landform',{etymology:E('Landform combines land and form; it names a natural shape of the Earth’s surface, such as a mountain, plain, coast, or cave.','landform'),contexts:[C('landform.s1','地理课堂','The class compared the U-shaped valley with the nearby coastal cliff as two different landforms.','全班把 U 形山谷与附近海岸峭壁进行比较，将它们作为两种不同地貌。','The class compared the U-shaped valley / with the nearby coastal cliff / as two different landforms.','landform 指地表自然形成的地貌形态。','山谷和海岸峭壁都是地表地貌。')],mistakes:[M('The worksheet called a bus timetable a landform even though it was a printed schedule, not a shape of the Earth’s surface.','The worksheet called the valley a landform because it was a natural shape of the terrain.','时刻表不是地表地貌。')],quiz:[Q('landform',1,1,'A landform is?','a natural shape of the Earth’s surface','a worker who owns a building','a kind of magazine','a natural shape of the Earth’s surface','landform 指地表自然形态。'),Q('landform',2,1,'Which is a landform?','a mountain range','a two-page invoice','a knitted stocking run','a mountain range','山脉是地貌形态。'),Q('landform',3,1,'A coastline can be studied as a?','landform','lamb','landlady','landform','海岸线属于地貌研究对象。'),Q('landform',4,1,'A cave, plain, or cliff is a feature of?','the land surface','a magazine issue','a lamp circuit','the land surface','这些都是地表或地形特征。')]});
D('landholder',{etymology:E('Landholder combines land and holder; it means someone who owns land or possesses it under a legal arrangement such as a lease.','landholder'),contexts:[C('landholder.s1','农业租赁','The landholder leased the northern field to a neighboring farmer for five growing seasons.','土地持有人把北边的田地租给邻近农户，租期为五个生长季。','The landholder leased the northern field / to a neighboring farmer / for five growing seasons.','landholder 指拥有土地或依法持有土地权益的人。','土地持有人将其土地出租给农户。')],mistakes:[M('The report called a visitor a landholder because he walked across a field once, although he owned or leased no land.','The report called the farmer who held a legal lease on the field a landholder.','短暂经过土地不构成所有或合法持有权益。')],quiz:[Q('landholder',1,1,'A landholder is someone who?','owns or legally holds land','visits a field once','manages a lampshade factory','owns or legally holds land','landholder 指土地所有人或合法持有人。'),Q('landholder',2,1,'A tenant with a long-term land lease may be a?','landholder','landform','ladybug','landholder','通过租赁依法持有土地的人也可称 landholder。'),Q('landholder',3,1,'Which document could show someone is a landholder?','a deed or valid land lease','a travel menu','a kymograph trace','a deed or valid land lease','产权文件或有效租约能证明土地权益。'),Q('landholder',4,1,'Landholder combines land with?','holder','lacerate','lagoon','holder','该词由 land 与 holder 构成。','word-formation')]});
D('landing',{etymology:E('Landing is formed from land with -ing; it can name an aircraft’s or boat’s arrival at ground or shore, or the flat platform at the top of stairs.','landing'),contexts:[C('landing.s2','住宅建筑','A small window on the landing brought daylight onto the flat space between the two flights of stairs.','楼梯平台上的一扇小窗把日光照进两段楼梯之间的平坦区域。','A small window on the landing / brought daylight / onto the flat space / between the two flights of stairs.','landing.s2 指楼梯顶部或两段楼梯之间的平坦平台。','平台位于两段楼梯之间。')],mistakes:[M('The apartment had no landing because the staircase contained a flat platform between its two flights.','The apartment’s staircase included a landing between the two flights.','楼梯之间有平坦平台，正是 landing。')],quiz:[Q('landing',1,1,'An aircraft landing is?','its arrival on the ground','its departure from the gate','a flat layer of sediment','its arrival on the ground','landing.s1 指飞机着陆。'),Q('landing',2,2,'A stair landing is?','a flat platform between or at the top of stairs','a wild animal’s den','a lake with no shore','a flat platform between or at the top of stairs','landing.s2 指楼梯平台。'),Q('landing',3,1,'A boat’s landing may be?','the act of coming ashore','a window above the stairs','a landholder’s deed','the act of coming ashore','船靠岸或人员上岸也可称 landing。'),Q('landing',4,2,'Which place has a landing?','the flat floor between two flights of stairs','the vertical face of every stair only','a buried waste site','the flat floor between two flights of stairs','楼梯段之间的平坦处是 landing。')]});
D('landlady',{etymology:E('Landlady combines land and lady and names a woman who rents a room, flat, or house to tenants.','landlady'),contexts:[C('landlady.s1','租房生活','The landlady gave the new tenants a spare key and explained how to report a leaking tap.','女房东给新租客一把备用钥匙，并说明如何报告水龙头漏水。','The landlady gave the new tenants a spare key / and explained / how to report / a leaking tap.','landlady 指把房屋或房间出租给租客的女性房东。','她负责把钥匙交给租客并说明房屋维护流程。')],mistakes:[M('The guest was the landlady even though she rented the room from the owner and received no rent from anyone.','The owner who rented rooms to the guests was the landlady.','只租房且不收租金的客人不是房东。')],quiz:[Q('landlady',1,1,'A landlady is a woman who?','rents property to tenants','rents a room from a tenant','owns a long-handled spoon','rents property to tenants','landlady 指女性房东。'),Q('landlady',2,1,'Which person is the landlady?','the owner who collects rent for the flat','the guest staying for one night','the maintenance worker hired for repairs','the owner who collects rent for the flat','收取房租的房屋出租者是 landlady。'),Q('landlady',3,1,'Landlady is the feminine counterpart of?','landlord','landform','landfill','landlord','landlady 与 landlord 对应。','word-formation'),Q('landlady',4,1,'A landlady may give tenants?','a key to the rented home','a map of a lagoon only','a medical prescription for a lamb','a key to the rented home','房东通常会向租客交付房屋钥匙。')]});
D('landless',{etymology:E('Landless combines land and the negative suffix -less; it describes people who own no land.','landless'),contexts:[C('landless.s1','土地改革','The landless families petitioned for access to plots where they could grow food and build secure homes.','没有土地的家庭请愿，希望获得可种植粮食并建造稳定住所的地块。','The landless families petitioned / for access to plots / where they could grow food / and build secure homes.','landless 指不拥有土地的。','这些家庭请求获得土地使用机会，说明他们没有自己的土地。')],mistakes:[M('The estate owners were described as landless even though each family held several large farms.','The families without any owned plots were described as landless.','拥有多块农场与 landless 的含义相反。')],quiz:[Q('landless',1,1,'A landless family?','owns no land','owns several farms','lives on an islet','owns no land','landless 指没有土地的。'),Q('landless',2,1,'Which person is landless?','a tenant who owns no plot of land','an estate owner with several farms','a landlord with multiple properties','a tenant who owns no plot of land','没有自有土地的租户属于 landless。'),Q('landless',3,1,'The suffix -less in landless means?','without','full of','able to','without','-less 表示“没有”。','word-formation'),Q('landless',4,1,'A landless worker may seek?','access to farmland or secure housing','a new lampshade','a kymograph recording','access to farmland or secure housing','没有土地的人可能寻求土地使用权或住所。')]});
D('landlocked',{etymology:E('Landlocked combines land and locked; it describes a country without a coastline or a place enclosed by land so that access to the sea is blocked.','landlocked'),contexts:[C('landlocked.s1','国际地理','The landlocked country depends on rail and road links through its neighbors to reach a seaport.','这个内陆国依靠穿越邻国的铁路和公路通道抵达海港。','The landlocked country depends on rail and road links / through its neighbors / to reach / a seaport.','landlocked 指没有海岸线、被陆地包围而无法直接通海的。','该国必须经邻国陆路前往海港。')],mistakes:[M('The island nation was landlocked even though it had a long coastline and several major seaports.','The inland country was landlocked because it had no coast of its own.','拥有海岸线和海港的国家不是 landlocked。')],quiz:[Q('landlocked',1,1,'A landlocked country has?','no coastline of its own','coasts on three oceans','no land borders','no coastline of its own','landlocked 指没有海岸线的国家。'),Q('landlocked',2,1,'A landlocked nation may need to cross neighbors to reach?','a seaport','a lampshade','a lambing season','a seaport','内陆国通常需经过邻国抵达港口。'),Q('landlocked',3,1,'Which country is landlocked?','one completely surrounded by other countries','an island with a long coast','a coastal state with several harbors','one completely surrounded by other countries','被其他国家围绕且无海岸线的是内陆国。'),Q('landlocked',4,1,'Landlocked is closest to?','without access to the sea','surrounded by water','a small lake','without access to the sea','没有海岸、无法直接通海是 landlocked。','confusable')]});
D('landlord',{etymology:E('Landlord combines land and lord; it refers to someone who owns and rents out property, and in British usage can also mean the owner or manager of a pub.','landlord'),contexts:[C('landlord.s2','英国酒吧','The pub’s landlord welcomed the folk band and arranged for the tables to be moved before the evening performance.','这家酒吧的老板欢迎民谣乐队，并安排在晚间演出前搬动桌子。','The pub’s landlord welcomed the folk band / and arranged / for the tables to be moved / before the evening performance.','landlord.s2 在英式用法中可指酒吧店主或经营者。','酒吧老板安排场地以便演出。')],mistakes:[M('The pub called the customer who rented a room for one night its landlord even though he owned and managed no property.','The pub called the person who owned and ran the establishment its landlord.','短期顾客不是拥有或经营酒吧的人。')],quiz:[Q('landlord',1,1,'A landlord generally?','owns property and rents it to others','pays rent to a property owner','supervises a laboratory','owns property and rents it to others','landlord.s1 指房东或出租人。'),Q('landlord',2,2,'In British usage, a pub landlord is?','the person who owns or runs the pub','a customer ordering dinner','a person with no land or property','the person who owns or runs the pub','landlord.s2 可指英国酒吧店主或经营者。'),Q('landlord',3,1,'Which person is a landlord?','the owner who rents an apartment to a tenant','the tenant paying rent','the visitor who borrows a key','the owner who rents an apartment to a tenant','出租公寓并收租的业主是房东。'),Q('landlord',4,1,'The opposite role to a landlord in a rental is usually the?','tenant','landform','landmass','tenant','tenant 是租客，与房东角色相对。','confusable')]});
D('landmark',{etymology:E('Landmark combines land and mark; it first named a visible feature used to identify a location and now also names a major event or achievement and, as an adjective, something historically significant.','landmark'),contexts:[C('landmark.s2','医学进展','The approval of the first effective treatment was a landmark in the history of the disease.','首种有效疗法获批，是这种疾病治疗史上的里程碑。','The approval of the first effective treatment / was a landmark / in the history / of the disease.','landmark.s2 指标志重要阶段的重大事件或成就。','新疗法获批改变了疾病治疗进程。')],mistakes:[M('The approval was a landmark even though it changed nothing, introduced no new treatment, and had no lasting importance.','The approval was a landmark because it opened a new stage in treatment.','没有重要影响或变化的普通事件不是里程碑。')],quiz:[Q('landmark',1,1,'A visible landmark helps people?','recognize where they are','serve soup','measure a body’s irritability','recognize where they are','landmark.s1 指便于辨认位置的地标。'),Q('landmark',2,2,'A landmark achievement marks?','an important stage or turning point','a routine event with no effect','a location’s rent payment','an important stage or turning point','landmark.s2 可指重要里程碑。'),Q('landmark',3,3,'A landmark court ruling is one that?','has major importance and changes later decisions','is an ordinary ruling with no broader effect','describes a coastal lagoon','has major importance and changes later decisions','landmark.s3 作形容词表示具有重大影响的。'),Q('landmark',4,1,'A tall tower used to navigate a city is a?','landmark','landfill','lamina','landmark','醒目的建筑可作为地标。')]});
D('landmass',{etymology:E('Landmass combines land and mass; it means a very large continuous area of land, such as a continent or major island.','landmass'),contexts:[C('landmass.s1','地理研究','A narrow sea separates the peninsula from the larger landmass to its north.','一片狭窄海域将半岛与北面更大的陆块隔开。','A narrow sea separates the peninsula / from the larger landmass / to its north.','landmass 指连续相连、面积很大的陆地。','半岛与北方大型陆块由海域分隔。')],mistakes:[M('The map called the tiny garden bed a landmass even though it covered only a few square meters.','The map called the continent-sized continuous area a landmass.','几平方米的小花坛不是大面积陆块。')],quiz:[Q('landmass',1,1,'A landmass is?','a very large continuous area of land','a thin layer of rock','a small spotted beetle','a very large continuous area of land','landmass 指大块连续陆地。'),Q('landmass',2,1,'Which could be a landmass?','a continent','a single garden plot','a staircase landing','a continent','大陆是典型的大型陆块。'),Q('landmass',3,1,'A peninsula may be connected to a larger?','landmass','lampshade','lacuna','landmass','半岛通常与更大的陆地相连。'),Q('landmass',4,1,'Landmass combines land with?','mass','lair','lambent','mass','landmass 表示一大片陆地。','word-formation')]});
D('landowner',{etymology:E('Landowner combines land and owner; it means someone who holds legal ownership of a piece of land, often an estate.','landowner'),contexts:[C('landowner.s1','土地保育','The landowner placed a conservation easement on the meadow, limiting construction while keeping the property in private ownership.','土地所有者为草甸设立保护地役权，在保留私人产权的同时限制开发。','The landowner placed a conservation easement / on the meadow / limiting construction / while keeping the property in private ownership.','landowner 指依法拥有土地的人。','土地所有者仍保有产权，同时通过地役权限制开发。')],mistakes:[M('The renter was the landowner even though the deed named another person as the legal owner.','The renter’s landlord was the landowner because the deed recorded that person’s title.','租户的身份不等于土地所有者。')],quiz:[Q('landowner',1,1,'A landowner is a person who?','legally owns land','has only visited the land','repairs a light on the land','legally owns land','landowner 指土地所有者。'),Q('landowner',2,1,'Which record can identify a landowner?','a deed naming the legal owner','a travel itinerary','a pub menu','a deed naming the legal owner','地契或产权记录可确认所有者。'),Q('landowner',3,1,'A landowner may grant someone?','permission to use a field','a kymograph','a lamb','permission to use a field','土地所有者可以授权他人使用土地。'),Q('landowner',4,1,'Landowner combines land with?','owner','lad','lag','owner','landowner 是 land 与 owner 组成的复合词。','word-formation')]});
D('landownership',{etymology:E('Landownership combines land, owner, and -ship; it means the legal condition or pattern of owning land.','landownership'),contexts:[C('landownership.s1','社会史研究','The historian traced changes in landownership by comparing estate maps and tax records from three centuries.','历史学家通过比较三个世纪的庄园地图和税务记录，追踪土地所有权的变化。','The historian traced changes in landownership / by comparing estate maps / and tax records / from three centuries.','landownership 指土地的法律所有权，也可指土地由谁持有的总体格局。','历史学家研究产权和所有人分布随时间的变化。')],mistakes:[M('The study of landownership ignored who held legal title and examined only the color of the fields on a modern map.','The study of landownership compared records showing who held title to the fields.','不研究土地归属，就没有分析土地所有权。')],quiz:[Q('landownership',1,1,'Landownership concerns?','who legally owns land','who lives near a lagoon','how to load cargo','who legally owns land','landownership 指土地所有权。'),Q('landownership',2,1,'A study of landownership may compare?','deeds and estate records','lamp brightness and color','types of ladybugs','deeds and estate records','产权文件可显示土地归属。'),Q('landownership',3,1,'Landownership is related to the noun?','landowner','landform','landfill','landowner','landownership 表示成为 landowner 的产权状态。','word-formation'),Q('landownership',4,1,'A change in landownership means?','legal title to land has changed hands','a hill has become a cliff','a magazine has a new issue','legal title to land has changed hands','土地所有权转移意味着产权易主。')]});
D('landscape',{etymology:E('Landscape entered English through Dutch landschap, “region or tract of land”; it can mean scenery, a painting of scenery, the general state of a field, or the verb for designing outdoor grounds.','landscape'),contexts:[C('landscape.s3','科技产业分析','The landscape of battery research changed after cheaper storage materials became commercially available.','更便宜的储能材料实现商业化后，电池研究领域的整体格局发生了变化。','The landscape of battery research changed / after cheaper storage materials / became commercially available.','landscape.s3 比喻某个领域的总体状况、格局或环境。','新材料的商业化改变了研究领域的条件和参与者。')],mistakes:[M('The landscape of the industry was unchanged even though new technology replaced its leading firms and transformed the market.','The landscape of the industry changed when new technology reshaped the market.','主要企业和市场均发生变化，不能称格局未变。')],quiz:[Q('landscape',1,1,'A landscape viewed from a hill is?','the scenery across an area of land','a single tree leaf','a legal owner of a field','the scenery across an area of land','landscape.s1 指一片区域的风景或地形。'),Q('landscape',2,2,'A landscape in an art gallery is?','a picture showing countryside or scenery','a landowner’s legal deed','a list of magazine issues','a picture showing countryside or scenery','landscape.s2 指风景画或山水画。'),Q('landscape',3,3,'The political landscape means?','the general situation and structure of politics','a painting of mountains only','a field covered in landfill','the general situation and structure of politics','landscape.s3 比喻某领域的整体格局。'),Q('landscape',4,4,'To landscape a yard is to?','design and plant the outdoor area','write a satirical article','load a ship with cargo','design and plant the outdoor area','landscape.s4 作动词表示设计和美化场地。')]});
D('landscapist',{etymology:E('Landscapist combines landscape and -ist; it names an artist whose principal subject is scenery or views of the natural world.','landscapist'),contexts:[C('landscapist.s1','艺术评论','The landscapist painted the coastal cliffs in muted colors, emphasizing the changing light rather than human figures.','这位风景画家用柔和的色彩描绘海岸峭壁，着重表现变化的光线，而非人物。','The landscapist painted the coastal cliffs / in muted colors / emphasizing the changing light / rather than human figures.','landscapist 指主要创作自然景色题材的画家。','画作重点是海岸景观和光线变化。')],mistakes:[M('The portrait painter was called a landscapist even though every canvas showed only close-up faces and no scenery.','The artist was called a landscapist because she mainly painted coasts, hills, and open country.','只画人像而不描绘风景不符合该词义。')],quiz:[Q('landscapist',1,1,'A landscapist mainly paints?','natural scenery','legal documents','laboratory equipment','natural scenery','landscapist 指风景画家。'),Q('landscapist',2,1,'Which artist is a landscapist?','one who paints mountains, rivers, and skies','one who paints only portraits','one who repairs landfills','one who paints mountains, rivers, and skies','描绘山川天空的画家属于风景画家。'),Q('landscapist',3,1,'Landscapist is formed from landscape plus?','-ist','-less','-ing','-ist','-ist 表示从事相关活动的人。','word-formation'),Q('landscapist',4,1,'A landscapist’s subject is most likely?','a valley at sunset','a close-up of a legal signature','a diagram of a kymograph','a valley at sunset','日落山谷是风景画题材。')]});
D('landslide',{etymology:E('Landslide combines land and slide; it can mean a sudden mass movement of earth or rock down a slope, or a decisive victory by a very large margin.','landslide'),contexts:[C('landslide.s2','选举结果','The incumbent won by a landslide, taking nearly three quarters of the vote in every region.','现任者以压倒性优势获胜，在每个地区都拿下近四分之三的选票。','The incumbent won by a landslide / taking nearly three quarters of the vote / in every region.','landslide.s2 比喻选举中以极大票数优势获胜。','胜者在各地区都获得大幅领先。')],mistakes:[M('The candidate won by a landslide after receiving fewer votes than the opponent in every district.','The candidate won by a landslide after winning by a very large vote margin.','在每个选区都落后，不能称压倒性获胜。')],quiz:[Q('landslide',1,1,'A geological landslide is?','a mass of earth or rock sliding down a slope','a thin layer of paper','a calm lake behind a sandbar','a mass of earth or rock sliding down a slope','landslide.s1 指山体或土石滑坡。'),Q('landslide',2,2,'A candidate wins by a landslide when?','the victory margin is very large','the vote is tied','the candidate loses every district','the victory margin is very large','landslide.s2 指压倒性胜利。'),Q('landslide',3,1,'Which event is a landslide?','a hillside collapses after days of rain','a lamp flickers softly','a worker is laid off','a hillside collapses after days of rain','山坡土石在降雨后滑落属于山体滑坡。'),Q('landslide',4,2,'“The party won in a landslide” is about?','an overwhelming election victory','a coastal landform','a damaged manuscript gap','an overwhelming election victory','政治语境下 landslide 指大胜。')]});
D('landslip',{etymology:E('Landslip combines land and slip; it is a variant term for a slide of soil or rock down a slope.','landslip'),contexts:[C('landslip.s1','山路养护','A landslip covered the lower mountain road with mud and loose stones after the overnight storm.','夜间风暴过后，一处塌方用泥土和松石覆盖了山路下段。','A landslip covered the lower mountain road / with mud and loose stones / after the overnight storm.','landslip 指土壤或岩石沿山坡滑下造成的塌方或滑坡。','泥石滑落并覆盖道路，说明发生了塌方。')],mistakes:[M('The road crew reported a landslip even though the hillside was stable and no soil or rock had moved.','The road crew reported a landslip after earth and rocks slid onto the road.','没有土石移动就没有发生滑坡。')],quiz:[Q('landslip',1,1,'A landslip is?','earth or rock sliding down a slope','a landowner’s contract','a tree-dwelling animal','earth or rock sliding down a slope','landslip 指土石滑坡或塌方。'),Q('landslip',2,1,'What might a landslip do to a road?','cover it with soil and stones','turn it into a lampshade','make it a lake','cover it with soil and stones','塌方可能把土石冲到路面上。'),Q('landslip',3,1,'A landslip is closely related to?','landslide','ladle','landlady','landslide','landslip 与 landslide 都指滑坡。','confusable'),Q('landslip',4,1,'After heavy rain, a warning about landslip risk concerns?','unstable ground moving downhill','a loose shoe lace','a broken lamp','unstable ground moving downhill','强雨后可能出现土石下滑。')]});
D('landsman',{etymology:E('Landsman combines land and man; it can mean a person inexperienced in sailing or, in another sense, someone from the same country or district as another.','landsman'),contexts:[C('landsman.s1','航海新手','The sailors gave the landsman a safety briefing before his first passage beyond the harbor.','水手们在这位不习航海的人首次驶出港口前，为他做了安全说明。','The sailors gave the landsman a safety briefing / before his first passage / beyond the harbor.','landsman.s1 指不熟悉航海、没有海上经验的人。','首次出海前需要对不习航海者进行安全说明。')],mistakes:[M('The experienced captain was called a landsman because he had spent decades at sea commanding ships.','The first-time passenger was called a landsman because he had no experience at sea.','长期航海的船长不是缺乏海上经验的人。')],quiz:[Q('landsman',1,1,'A landsman aboard a ship may be?','someone inexperienced at sea','the ship’s most seasoned captain','a type of landform','someone inexperienced at sea','landsman.s1 指不习航海的人。'),Q('landsman',2,2,'A traveler may call another person a landsman if they?','come from the same country or district','work on different ships','own separate lakes','come from the same country or district','landsman.s2 指同乡或同胞。'),Q('landsman',3,1,'Which passenger is a landsman in the nautical sense?','a first-time traveler who has never sailed','a sailor with twenty years at sea','the harbor pilot guiding a ship','a first-time traveler who has never sailed','首次出海者缺乏航海经验。'),Q('landsman',4,2,'Two people from the same home district may describe each other as?','landsmen','landslides','landlords','landsmen','landsman.s2 的复数 landsmen 可指同乡。')]});
D('landward',{etymology:E('Landward combines land with the directional suffix -ward; it describes a direction or position facing or moving toward land.','landward'),contexts:[C('landward.s2','海岸航行','After rounding the point, the fishing boat turned landward and headed toward the harbor entrance.','绕过岬角后，渔船转向陆地，朝港口入口驶去。','After rounding the point / the fishing boat turned landward / and headed toward / the harbor entrance.','landward.s2 作副词，表示朝陆地方向移动。','船从海上转向海岸港口。')],mistakes:[M('The boat sailed landward by leaving the coast behind and steering farther out to sea.','The boat sailed landward by steering from open water toward the coast.','驶离海岸、驶向外海与 landward 方向相反。')],quiz:[Q('landward',1,1,'A landward-facing window looks?','toward the land','out toward open sea only','down into a landfill','toward the land','landward.s1 可作形容词表示朝陆的。'),Q('landward',2,2,'To sail landward is to sail?','in the direction of the land','away from every coast','around a swimming pool','in the direction of the land','landward.s2 作副词表示向陆地。'),Q('landward',3,1,'Which path is landward?','from the beach toward inland fields','from the harbor out to the open sea','from one end of a pool to the other','from the beach toward inland fields','从海滩向内陆行进是 landward。'),Q('landward',4,1,'Landward combines land with a suffix meaning?','in a direction toward','a person who owns','without','in a direction toward','-ward 表示方向。','word-formation')]});
D('lane',{etymology:E('Lane comes from Old English lanu, a narrow passage; it can mean a small road, a marked traffic division, or a designated route for swimming, running, or ships.','lane'),contexts:[C('lane.s2','道路安全','The driver moved into the left lane only after checking the mirror and signaling.','司机确认后视镜并打转向灯后，才驶入左侧车道。','The driver moved into the left lane / only after checking the mirror / and signaling.','lane.s2 指宽路上用标线划分出的行车道。','车辆驶入道路上特定的一条车道。')],mistakes:[M('The car changed lanes by moving from the marked left division into the same division without crossing a lane marking.','The car changed lanes by crossing the marking into the adjacent division of the road.','没有进入另一条车道就没有变道。')],quiz:[Q('lane',1,1,'A country lane is usually?','a narrow rural road','a wide ocean','a kind of insect','a narrow rural road','lane.s1 指乡间小路或狭窄道路。'),Q('lane',2,2,'A driver should remain in the marked?','lane','lair','lamina','lane','lane.s2 指车道。'),Q('lane',3,3,'A swimming lane marks?','the path assigned to one swimmer','a road used by cars','a narrow country alley','the path assigned to one swimmer','lane.s3 可指泳道或跑道分道。'),Q('lane',4,3,'A ship’s lane can be?','a marked route for vessels','a basement room for experiments','a staircase platform','a marked route for vessels','lane.s3 也可指船舶航线。')]});
D('language',{etymology:E('Language comes through Old French langage from Latin lingua “tongue”; it can mean a human communication system, a style of wording, professional terminology, or a programming system.','language'),contexts:[C('language.s3','医疗沟通','The surgeon avoided technical language and explained the risks in words the patient could understand.','外科医生避免使用专业术语，而用患者能理解的话说明风险。','The surgeon avoided technical language / and explained the risks / in words / the patient could understand.','language.s3 指某一专业领域使用的术语或行话。','医生把专业表达改成通俗易懂的话。')],mistakes:[M('The doctor used plain everyday language by filling the explanation with unexplained surgical abbreviations and specialist terminology.','The doctor avoided medical language by replacing unfamiliar terms with ordinary words.','大量不解释的专业术语不是通俗日常用语。')],quiz:[Q('language',1,1,'A language such as English is?','a system of human communication using words','a single legal document','a marked division on a road','a system of human communication using words','language.s1 指人类交流所用的语言系统。'),Q('language',2,2,'“The report uses cautious language” refers to its?','style and choice of words','computer hardware','geographic route','style and choice of words','language.s2 指措辞或文风。'),Q('language',3,3,'A medical language may include?','specialist terms used by healthcare workers','only everyday greetings','a set of swimming lanes','specialist terms used by healthcare workers','language.s3 指专业术语。'),Q('language',4,4,'Python is a programming language because it?','provides instructions for a computer program','is a human dialect spoken in Rome','describes a country lane','provides instructions for a computer program','language.s4 指编写计算机程序的指令系统。')]});
D('languid',{etymology:E('Languid comes from Latin languidus, from languere “to be weak”; it describes tired low energy or a slow, relaxed manner.','languid'),contexts:[C('languid.s2','夏日午后','A languid breeze moved the curtains while the guests rested in the shade after lunch.','午餐后，客人在阴凉处休息，一阵慵懒的微风吹动窗帘。','A languid breeze moved the curtains / while the guests rested / in the shade / after lunch.','languid.s2 描写节奏缓慢、轻松慵懒的动作或气氛。','轻风缓缓吹动，营造松弛氛围。')],mistakes:[M('The languid march moved at a punishing sprinting pace and left every participant breathless.','The languid march proceeded slowly and gently through the warm afternoon.','惩罚性快跑节奏并不缓慢慵懒。')],quiz:[Q('languid',1,1,'A languid person may seem?','weak and low in energy','highly energetic and hurried','eager to climb a ladder','weak and low in energy','languid.s1 指倦怠无力的。'),Q('languid',2,2,'A languid afternoon is?','slow and pleasantly relaxed','busy and frantic','cold and irreversible','slow and pleasantly relaxed','languid.s2 指缓慢慵懒而放松的。'),Q('languid',3,1,'Which movement is languid?','a slow, unhurried stretch in the sun','a sudden sprint to catch a bus','a rapid emergency response','a slow, unhurried stretch in the sun','在阳光下慢慢伸展显得慵懒。'),Q('languid',4,1,'Languid is closest to?','listless','laborsaving','landlocked','listless','listless 可描述无精打采，与 languid 接近。','confusable')]});
D('languish',{etymology:E('Languish comes through Old French from Latin languere “to be weak”; it means grow weak or remain stalled without progress.','languish'),contexts:[C('languish.s1','项目停滞','Without a new funding decision, the restoration project continued to languish in the planning office for another year.','由于没有新的资金决定，修复项目又在规划办公室里停滞了一年。','Without a new funding decision / the restoration project continued to languish / in the planning office / for another year.','languish 指逐渐衰弱，也可指长期停滞、得不到发展。','项目因缺少资金决定而迟迟没有进展。')],mistakes:[M('The proposal languished because it received immediate funding, finished ahead of schedule, and expanded into a completed program.','The proposal languished for months without funding or a decision.','迅速获资并完成项目，与停滞不前相反。')],quiz:[Q('languish',1,1,'A project that languishes?','fails to make progress for a long time','finishes ahead of schedule','wins by a landslide','fails to make progress for a long time','languish 可指长期停滞。'),Q('languish',2,1,'A neglected plant may languish by?','growing weak','producing vigorous new leaves','becoming a landform','growing weak','该词也可表示变得衰弱。'),Q('languish',3,1,'Which sentence uses languish correctly?','The appeal languished for months without a hearing.','The appeal languished by being resolved immediately.','The appeal languished into a lampshade.','The appeal languished for months without a hearing.','长期没有开庭说明上诉案停滞。'),Q('languish',4,1,'A proposal is languishing if it is?','left inactive and not advancing','actively being completed','already approved and funded','left inactive and not advancing','没有推进的提案处于停滞状态。')]});
D('languishing',{etymology:E('Languishing is the present participle of languish and an adjective for something growing weak or being neglected; it can also describe an affected yearning expression.','languishing'),contexts:[C('languishing.s1','动物救护','The once-bright orchid was languishing in a dark corner, with drooping leaves and no new growth.','这株曾经鲜亮的兰花在阴暗角落里渐渐衰弱，叶片下垂，也没有新芽。','The once-bright orchid was languishing / in a dark corner / with drooping leaves / and no new growth.','languishing.s1 描述正在衰弱、被忽视或没有好转的状态。','植株叶片下垂且不再生长，显示状况变差。')],mistakes:[M('The orchid was languishing because it was thriving, producing healthy leaves, and flowering continuously.','The orchid was languishing because it was neglected and its leaves were drooping.','健康旺盛地生长与 languishing 的衰弱义相反。')],quiz:[Q('languishing',1,1,'A languishing garden?','is growing weak or being neglected','is flourishing with constant care','is a marked road division','is growing weak or being neglected','languishing.s1 指衰弱或被冷落的。'),Q('languishing',2,2,'A languishing look may be?','a romantic, yearning expression','a safety warning lamp','a plain country lane','a romantic, yearning expression','languishing.s2 可指含情脉脉、渴望的神情。'),Q('languishing',3,1,'Which plant looks languishing?','one with drooping leaves and no new growth','one with healthy shoots and flowers','one recently planted in rich soil and thriving','one with drooping leaves and no new growth','叶片下垂、无新生长体现衰弱。'),Q('languishing',4,2,'The adjective languishing in a romance novel may describe?','a yearning gaze','a small coastal pool','a job dismissal','a yearning gaze','含情脉脉的目光可用 languishing 描写。')]});
D('lank',{etymology:E('Lank comes from Old English hlanc; it describes hair that hangs long and straight without body, or a person who is tall and thin.','lank'),contexts:[C('lank.s1','人物描写','The lank teenager’s long, straight hair fell flat against his shoulders after the rain.','这名瘦高少年的长直发淋雨后贴着肩膀垂下来。','The lank teenager’s long, straight hair / fell flat / against his shoulders / after the rain.','lank 可形容缺乏蓬松感的长直发，也可指瘦长的人。','头发又直又贴，不蓬松；人物也显得瘦高。')],mistakes:[M('The stylist called the hair lank even though it was short, tightly curled, and full of volume.','The stylist called the long, straight, flat hair lank.','短卷且蓬松的头发不符合 lank 的描述。')],quiz:[Q('lank',1,1,'Lank hair is often?','long, straight, and lacking body','short, tightly curled, and thick','softly flickering with light','long, straight, and lacking body','lank.s1 可形容平直、缺乏蓬松感的头发。'),Q('lank',2,1,'A lank person is typically?','tall and thin','short and broad','a small beetle','tall and thin','lank 也可形容瘦长的人。'),Q('lank',3,1,'Which hairstyle looks lank?','long straight strands lying flat','short dense curls with volume','a neatly tied shoe cord','long straight strands lying flat','平直贴服、没有蓬松感的头发符合 lank。'),Q('lank',4,1,'Lank is closest in the hair sense to?','limp and flat','thick and bouncy','lambent','limp and flat','limp and flat 描写头发没有蓬松度。','confusable')]});
D('lantern',{etymology:E('Lantern comes through Latin lanterna and Greek lamptēr, an enclosed lamp; it names a portable light protected by a case.','lantern'),contexts:[C('lantern.s1','露营准备','She hung a battery lantern from the tent pole so the family could pack safely after sunset.','日落后，她把一盏电池灯笼挂在帐篷杆上，让家人能够安全收拾东西。','She hung a battery lantern / from the tent pole / so the family could pack safely / after sunset.','lantern 指有外壳保护、可提携或悬挂的灯。','灯笼在户外提供照明且灯源受外壳保护。')],mistakes:[M('The camper carried a lantern that had no case around its flame and could not provide any light.','The camper carried an enclosed lantern that protected the flame and lit the path.','没有灯源或保护外壳的物品不符合此处 lantern 的意思。')],quiz:[Q('lantern',1,1,'A lantern is a lamp protected by?','a case or enclosure','a shoe lace','a thin layer of sediment','a case or enclosure','lantern 指带外壳保护的灯。'),Q('lantern',2,1,'Which light is a lantern?','a portable enclosed lamp used outdoors','an uncovered window with sunlight','a red indicator on a dashboard only','a portable enclosed lamp used outdoors','户外可携带的有罩灯具是 lantern。'),Q('lantern',3,1,'A camper may hang a lantern to?','light a tent after dark','cover a manuscript gap','mark a swimming lap','light a tent after dark','灯笼可为夜间帐篷提供照明。'),Q('lantern',4,1,'Lantern is related in history to a word for?','lamp or light','land ownership','a legal theft','lamp or light','词源与灯或照明有关。','word-formation')]});
D('lap',{etymology:E('Lap has several established senses: the area across the upper legs when seated, one circuit of a course, drinking with the tongue, or small waves touching a shore.','lap'),contexts:[C('lap.s2','游泳训练','After every lap, the swimmer paused at the wall to check the time and adjust her breathing.','每游完一圈，游泳者都会在池壁边停下查看时间并调整呼吸。','After every lap / the swimmer paused at the wall / to check the time / and adjust her breathing.','lap.s2 指跑道或泳池中绕行一整圈或往返一次。','游泳者每完成一圈就在池壁处停下。')],mistakes:[M('The swimmer counted a lap each time she crossed only halfway down the pool and turned back immediately.','The swimmer counted a lap after she completed the full course length and returned to the starting end.','仅游到中点就折返没有完成一整圈或一次完整往返。')],quiz:[Q('lap',1,1,'When seated, a person’s lap is?','the flat area across the upper legs','a full circuit around a track','a metal lamp cover','the flat area across the upper legs','lap.s1 指坐着时大腿形成的平面。'),Q('lap',2,2,'A swimmer completes a lap by?','covering one complete course length or circuit','standing still at the pool entrance','drinking water with a spoon','covering one complete course length or circuit','lap.s2 指泳池中的一圈或一次往返。'),Q('lap',3,3,'A cat may lap water by?','drinking it with its tongue','pouring it into a lantern','walking a country lane','drinking it with its tongue','lap.s3 指动物用舌头舔饮。'),Q('lap',4,4,'Small waves lap against a shore when they?','touch it repeatedly and gently','bury it under soil','form a landslide','touch it repeatedly and gently','lap.s4 描述小浪反复轻拍岸边。')]});
D('lapse',{etymology:E('Lapse comes from Latin lapsus “slip or fall”; it can name the end of a valid period or a small careless mistake.','lapse'),contexts:[C('lapse.s1','保险续期','There was a brief lapse in coverage after the old policy expired and before the renewal payment was processed.','旧保单到期后、新的续费尚未处理前，保险保障曾短暂中断。','There was a brief lapse in coverage / after the old policy expired / and before the renewal payment / was processed.','lapse 作名词可指有效期结束或短暂中断，也可指疏忽造成的小错误。','保单到期与新保单生效之间出现空档。')],mistakes:[M('The insurance policy had a lapse even though the old term and the renewal overlapped continuously with no break in coverage.','The insurance policy had a lapse because the old term ended before the renewal began.','保障期间连续重叠，没有中断空档。')],quiz:[Q('lapse',1,1,'A lapse in a license means?','its valid period has ended','it has just been issued','it has been laminated','its valid period has ended','lapse 可指有效期限届满。'),Q('lapse',2,1,'A lapse in concentration is?','a brief failure of attention','a permanent legal ownership','a marked traffic lane','a brief failure of attention','lapse 也可指一时疏忽。'),Q('lapse',3,1,'Which is a lapse of memory?','forgetting a familiar name for a moment','remembering every detail correctly','following a clear itinerary','forgetting a familiar name for a moment','短暂忘记姓名属于记忆疏忽。'),Q('lapse',4,1,'If insurance lapses, the coverage?','expires or stops being active','becomes a landform','gets a lampshade','expires or stops being active','lapse 作动词可表示保单失效。')]});
D('laptop',{etymology:E('Laptop combines lap and top, referring to a portable computer designed to rest on a person’s lap; it can distinguish that computer from a desktop.','laptop'),contexts:[C('laptop.s1','远程办公','She opened her laptop at the library table and joined the video meeting using the built-in camera.','她在图书馆桌边打开笔记本电脑，并使用内置摄像头加入视频会议。','She opened her laptop at the library table / and joined the video meeting / using the built-in camera.','laptop 指屏幕和键盘可折叠在一起的小型便携式电脑。','设备便于携带，并可在桌面上打开使用。')],mistakes:[M('He carried a laptop that weighed several tons and required a separate full-size screen, keyboard, and desk to operate.','He carried a laptop with a folding screen and keyboard that could run on its own battery.','需要固定桌面和独立设备的大型机器不符合便携式电脑特征。')],quiz:[Q('laptop',1,1,'A laptop is a?','portable computer with a folding screen and keyboard','device used to serve soup','kind of coastal lagoon','portable computer with a folding screen and keyboard','laptop.s1 指带折叠屏幕和键盘的便携电脑。'),Q('laptop',2,2,'“Use my laptop, not my desktop” distinguishes?','a portable computer from a stationary computer','a country lane from a city road','a landowner from a tenant','a portable computer from a stationary computer','laptop.s2 强调便携电脑相对于台式机。'),Q('laptop',3,1,'Which device is a laptop?','a battery-powered computer that folds shut','a monitor mounted permanently to a wall','a handheld paper notebook','a battery-powered computer that folds shut','可折叠并使用电池的电脑是 laptop。'),Q('laptop',4,1,'The name laptop refers to its portability for use?','on or near a person’s lap','inside a landfill','under a swimming lane','on or near a person’s lap','名称来自可放在膝上使用的便携特性。','word-formation')]});
D('larboard',{etymology:E('Larboard is the historical maritime term for a ship’s left side when facing forward; its earlier formation is uncertain, and port later became the clearer standard term.','larboard'),contexts:[C('larboard.s1','航海术语','The mate stood on the larboard side, facing the bow, while the vessel approached the narrow channel.','船只驶近狭窄航道时，大副面朝船头站在左舷。','The mate stood on the larboard side / facing the bow / while the vessel approached / the narrow channel.','larboard 指面朝船首时船的左舷，是历史航海用语；现代通常说 port。','以面向船头为基准，大副所在的一侧为左舷。')],mistakes:[M('The captain called the vessel’s right side larboard while facing forward, although that side is starboard.','The captain called the vessel’s left side larboard while facing forward.','面朝船头时右侧是 starboard，larboard 指左侧。')],quiz:[Q('larboard',1,1,'Larboard is which side of a ship when facing forward?','the left side','the right side','the upper deck','the left side','larboard.s1 指船首朝向前方时的左舷。'),Q('larboard',2,1,'Which modern term is clearer than larboard?','port','starboard','lair','port','为避免与 starboard 混淆，现代通常使用 port。'),Q('larboard',3,1,'A sailor facing the bow has larboard to the?','left','right','rear only','left','左舷按面向船首时的左侧确定。'),Q('larboard',4,1,'Larboard is mainly a?','historical nautical term','word for a small island','term for a theater painting','historical nautical term','larboard 是历史航海词。','register')]});
D('larceny',{etymology:E('Larceny comes through Anglo-French larcin from Latin latrocinium; it names the crime of secretly taking another person’s property.','larceny'),contexts:[C('larceny.s1','刑事法律','The prosecutor charged the employee with larceny after security footage showed him secretly removing cash from the register.','监控录像显示该员工偷偷从收银机取走现金后，检察官以盗窃罪起诉了他。','The prosecutor charged the employee with larceny / after security footage showed him / secretly removing cash / from the register.','larceny 指秘密窃取他人财物的犯罪。','录像显示员工未经许可秘密拿走现金。')],mistakes:[M('The report called the returned wallet larceny even though its owner had lent it to the borrower and consented to the use.','The report described secretly taking another person’s wallet without consent as larceny.','经所有者同意借用财物不属于秘密盗窃。')],quiz:[Q('larceny',1,1,'Larceny is the crime of?','secretly taking someone else’s property','legally renting a home','damaging a hillside in a storm','secretly taking someone else’s property','larceny 指盗窃罪。'),Q('larceny',2,1,'Which act could constitute larceny?','secretly removing a coworker’s cash without permission','borrowing a tool after receiving permission','buying a used lamp from its owner','secretly removing a coworker’s cash without permission','未经允许秘密拿走钱财符合盗窃罪概念。'),Q('larceny',3,1,'A key feature of larceny is taking property?','without the owner’s consent','with a signed loan agreement','as a gift from the owner','without the owner’s consent','未经所有者同意是关键。'),Q('larceny',4,1,'Larceny is a?','criminal offense','type of lagoon','word for a legal landowner','criminal offense','larceny 是刑事犯罪。')]});
D('large',{etymology:E('Large comes through Old French from Latin largus “abundant”; it can describe physical size, amount or number, and in the phrase at large mean generally or still free.','large'),contexts:[C('large.s2','城市预算','A large share of the city budget went to repairing roads damaged by the winter storms.','市政府预算中很大一部分用于修复冬季风暴损坏的道路。','A large share of the city budget / went to repairing roads / damaged by the winter storms.','large.s2 表示数量或份额大的。','相当大比例的预算被用于道路维修。')],mistakes:[M('The town spent a large amount on repairs even though the total was only one cent and represented none of its budget.','The town spent a large amount on repairs, consuming nearly half its annual budget.','极小金额且占预算比例为零，不符合“大量”的含义。')],quiz:[Q('large',1,1,'A large suitcase is?','bigger than usual in physical size','a short period of time','a tiny insect','bigger than usual in physical size','large.s1 描述物体尺寸大。'),Q('large',2,2,'A large number of visitors means?','many visitors','one visitor','no visitors','many visitors','large.s2 指数量多。'),Q('large',3,3,'“The suspect remains at large” means the suspect is?','still free and not yet captured','inside a prison cell','a landowner','still free and not yet captured','at large 可指逃脱后仍未被捕。'),Q('large',4,3,'“The team, at large, supported the proposal” means?','the team generally supported it','one member secretly opposed it','the proposal was physically big','the team generally supported it','at large 也可表示整体上或普遍地。')]});
D('large-scale',{etymology:E('Large-scale combines large and scale; it describes an operation over a wide area or involving many resources, and a map that depicts a smaller area in greater detail.','large-scale'),contexts:[C('large-scale.s2','地图制图','The large-scale map shows individual streets and building entrances across the compact historic district.','这幅大比例尺地图详细标出了这片紧凑历史街区的单条街道和建筑入口。','The large-scale map shows / individual streets and building entrances / across the compact / historic district.','large-scale.s2 描述地图比例尺较大，因此显示较小区域的更多细节。','地图覆盖范围较小，但可见街道与入口细节。')],mistakes:[M('The large-scale map showed an entire continent with almost no detail because it covered an enormous area.','The large-scale map showed a compact district with detailed street and building information.','覆盖大陆且细节很少属于小比例尺地图。')],quiz:[Q('large-scale',1,1,'A large-scale project involves?','many people or resources over a wide scope','one small task with no resources','a single narrow traffic lane','many people or resources over a wide scope','large-scale.s1 指大规模的。'),Q('large-scale',2,2,'A large-scale map usually shows?','a relatively small area in considerable detail','the entire globe with minimal detail','only one street name','a relatively small area in considerable detail','large-scale.s2 指大比例尺、细节较多的地图。'),Q('large-scale',3,1,'Which is a large-scale operation?','a nationwide vaccination campaign','one person labeling a single box','a short note to a neighbor','a nationwide vaccination campaign','覆盖全国的大型项目属于大规模行动。'),Q('large-scale',4,2,'A detailed neighborhood plan is likely a?','large-scale map','small-scale world map','landfill diagram only','large-scale map','街区范围小且细节多，使用大比例尺地图。')]});
D('largely',{etymology:E('Largely is formed from large with -ly; it means mostly or to a great extent, and in another use in large amounts or numbers.','largely'),contexts:[C('largely.s1','材料研究','The building is largely made of recycled brick, although its roof frame uses new steel.','这座建筑大体上由回收砖块建成，不过屋顶框架使用了新钢材。','The building is largely made of recycled brick / although its roof frame / uses new steel.','largely.s1 表示主要地或大体上。','主体材料是回收砖，但仍有一部分使用新钢材。')],mistakes:[M('The report said the building was largely made of brick even though nearly every wall and floor was constructed from glass and steel.','The report said the building was largely made of brick because most of its structure used reclaimed masonry.','砖块仅占很小部分，与“主要由砖构成”相矛盾。')],quiz:[Q('largely',1,1,'If a task is largely complete, it is?','mostly complete','not started at all','completely impossible','mostly complete','largely.s1 表示大体上、主要地。'),Q('largely',2,2,'If goods are produced largely, they are produced?','in large amounts or numbers','only one at a time','with no materials','in large amounts or numbers','largely.s2 可表示大量地。'),Q('largely',3,1,'“The success was largely due to teamwork” means it was?','mostly due to teamwork','unrelated to teamwork','caused only by a storm','mostly due to teamwork','largely due to 表示主要归因于。'),Q('largely',4,1,'Largely is the adverb related to?','large','lank','larva','large','largely 由 large 加 -ly 构成。','word-formation')]});
D('largish',{etymology:E('Largish is formed from large with the informal suffix -ish; it means somewhat or fairly large, without claiming an exact size.','largish'),contexts:[C('largish.s1','家具选购','They chose a largish dining table that could seat eight people but still fit the narrow room.','他们选了一张比较大的餐桌，能坐八个人，但仍放得进狭长的房间。','They chose a largish dining table / that could seat eight people / but still fit / the narrow room.','largish 是非正式形容词，表示颇大或比较大。','桌子比普通餐桌大，但仍适合房间尺寸。')],mistakes:[M('The buyer called the miniature side table largish even though it was smaller than a book and could hold no plate.','The buyer called the eight-seat dining table largish because it was bigger than a usual small table.','比书还小的桌子不能恰当地称为比较大。')],quiz:[Q('largish',1,1,'A largish room is?','somewhat large','extremely tiny','exactly measured as one meter','somewhat large','largish 表示颇大或有些大。'),Q('largish',2,1,'Which object is largish?','a dining table that seats eight in a small room','a coin-sized table','a tiny bead','a dining table that seats eight in a small room','能坐八人的餐桌相对较大。'),Q('largish',3,1,'The suffix -ish in largish softens the claim to?','somewhat large','not large at all','larger than every possible object','somewhat large','-ish 表示“大约、颇为”而非绝对程度。','word-formation'),Q('largish',4,1,'Largish is an informal alternative to?','fairly large','irrelevant','landlocked','fairly large','fairly large 与 largish 意思接近。','confusable')]});
D('lark',{etymology:E('Lark has two established senses: a small songbird, from Old English lawerce, and an informal word for a playful activity or silly fun; the latter history is uncertain.','lark'),contexts:[C('lark.s1','野外观察','At dawn, a lark rose above the field and sang while the mist still covered the grass.','黎明时，一只云雀飞到田野上空鸣唱，草地上仍覆盖着薄雾。','At dawn / a lark rose above the field / and sang / while the mist still covered the grass.','lark.s1 指一种以高空鸣唱著称的小型鸟类。','清晨在田野上空鸣唱是云雀的典型景象。')],mistakes:[M('The birdwatcher identified the silent metal lantern as a lark even though it had no feathers or voice.','The birdwatcher identified the small bird singing above the field as a lark.','灯笼不是鸟类，不能称为 lark。')],quiz:[Q('lark',1,1,'A lark is a small bird known for?','singing high in the air','building a lampshade','swimming a lap underwater','singing high in the air','lark.s1 指以高空鸣唱著称的云雀。'),Q('lark',2,2,'“We went on a lark” means we went?','for fun or playful amusement','to commit larceny','to purchase land','for fun or playful amusement','lark.s2 可指嬉戏或为好玩而做的事。'),Q('lark',3,1,'Which sight is a lark?','a small bird singing over a meadow','a deer sleeping in a lair','a crew loading cargo','a small bird singing over a meadow','草地上空鸣唱的小鸟是云雀。'),Q('lark',4,2,'If friends lark about, they?','play around in a silly way','work quietly on a lab report','remain landlocked','play around in a silly way','lark 作动词可表示嬉戏玩闹。')]});
D('larva',{etymology:E('Larva comes from Latin larva “mask or ghost”; in modern biology it names an immature insect form that precedes the adult stage.','larva'),contexts:[C('larva.s1','昆虫学','The larva fed on the leaf before forming a pupa and later emerging as an adult beetle.','幼虫先以叶片为食，随后形成蛹，最终羽化为成年甲虫。','The larva fed on the leaf / before forming a pupa / and later emerging / as an adult beetle.','larva 指昆虫尚未成为成虫前的幼体阶段。','幼体进食后化蛹，再发育为成虫。')],mistakes:[M('The entomologist called the fully winged adult beetle a larva after it had completed metamorphosis.','The entomologist called the immature stage before pupation a larva.','完成变态的有翅成虫不是幼虫。')],quiz:[Q('larva',1,1,'A larva is?','an immature insect stage before adulthood','a fully developed adult insect','a type of coastal landform','an immature insect stage before adulthood','larva 指昆虫的幼体阶段。'),Q('larva',2,1,'A larva may later become a?','pupa and then an adult','landowner','lambent light','pupa and then an adult','许多昆虫幼虫先化蛹再成为成虫。'),Q('larva',3,1,'Which insect stage is a larva?','a caterpillar before it becomes a butterfly','a fully grown butterfly with wings','a bird singing over a field','a caterpillar before it becomes a butterfly','毛虫是蝴蝶成虫前的幼虫。'),Q('larva',4,1,'Larva is a term used in?','biology','real-estate law only','road design','biology','larva 是生物学术语。')]});
D('larval',{etymology:E('Larval is formed from larva with the adjective suffix -al; it means relating to or occurring during the larva stage.','larval'),contexts:[C('larval.s1','昆虫发育','The larval stage lasts several weeks, during which the caterpillar feeds and grows before pupation.','幼虫期持续数周，其间毛虫不断进食和生长，之后才会化蛹。','The larval stage lasts several weeks / during which the caterpillar feeds and grows / before pupation.','larval 指与幼虫阶段有关或发生在幼虫期的。','毛虫在化蛹前的进食和生长属于幼虫期活动。')],mistakes:[M('The biologist described the winged adult’s mating behavior as larval even though it occurred after the insect had matured.','The biologist described the caterpillar’s feeding period before pupation as larval.','成虫阶段发生的行为不属于幼虫期。')],quiz:[Q('larval',1,1,'Larval development occurs during the?','immature stage before adulthood','fully mature adult stage only','period after an animal dies','immature stage before adulthood','larval 指幼虫期的。'),Q('larval',2,1,'A larval feeding pattern is a pattern of?','feeding while the insect is a larva','feeding by a fully mature adult only','a landowner’s diet','feeding while the insect is a larva','幼虫进食方式属于 larval pattern。'),Q('larval',3,1,'Larval is the adjective related to?','larva','lark','larceny','larva','larval 由 larva 加 -al 构成。','word-formation'),Q('larval',4,1,'A larval form is?','an immature form of an animal','a country lane','a legal owner of land','an immature form of an animal','larval form 指动物的幼体形态。')]});

})();
